  /* ===================================================================
     1. CONFIG — the knobs a new game changes first.
     =================================================================== */
  var CONFIG = {
    title:   "Triverse",
    /* One sentence, and nothing else: the demo caption is dropped in the SKIN
       because the stage below already plays the two right hops and the left. */
    tagline: "<b class=\"w-swipe\">Swipe</b> to jump from <b class=\"w-path\">path</b> to <b class=\"w-path\">path</b>",
    gameSeconds: 0,                  // endless: the run ends when the lives do

    // Store links used by every CTA. The right one is picked at runtime from the
    // user agent. Until this game has a real listing all three point at the
    // newrare site, where the game can actually be played — never leave a
    // placeholder store URL here, it ships as a 404 on the device.
    storeUrl: {
      ios:     "https://newrare.app/#playables",
      android: "https://newrare.app/#playables",
      fallback:"https://newrare.app/#playables"
    },

    // Design resolution — all game logic and all DOM overlays use these units.
    designWidth: 720,
    designHeight: 1280,
    bg: "#04050f",

    layout: { hudHeight: 150, ctaHeight: 112, sideMargin: 30 },

    // The mechanic is a lateral flick, so the intro shows the swipe demo.
    intro: { logo: "logo", demo: "swipe", caption: "",
             // on a desk: the arrows (shell.js, Demo)
             desk: [{ keys: ["left", "right"], does: "Change path" },
                    { keys: ["up"], does: "Jump" }] },

    // Desktop: SPACE starts and replays, and the LEFT/RIGHT arrows (or A/D)
    // fire the lateral flick — the engine synthesizes the whole gesture, so the
    // swipe handlers below are the only input code this game owns.
    keyboard: true,
    swipeUp: true,                   // UP (or W) is the jump: an upward flick, like a finger's

    // Endless run: the lives pill replaces the clock in the right HUD slot.
    hud: { score: true, timer: false },

    /* The bed. The web build ships the whole track (web.music) and each biome
       loops its own window of it (CONFIG.biomes[].music); the menus get the
       track's opening, slowed and halved so it reads as OTHER music rather
       than the round's played quietly. Cut on the track's own phrase seams
       (123.5 BPM, eight bars = 15.55 s, measured — docs/MUSIC.md). */
    /* `seam`: every window loops on the bar, two beats of crossfade ending on
       its downbeat (docs/MUSIC.md, The seam); `cut`: the playable's window,
       one seam of pre-roll into its embedded cut. */
    music: { volume: 0.12, fade: 1.6, seam: 0.97,
             cut: { from: 0.97, length: 29.188 },
             menu: { from: 1.5, length: 31.142, rate: 0.85, gain: 0.5 } },

    // All user-facing copy in one place.
    copy: {
      start:      "Tap to play",
      ctaBar:     "Install now",
      ctaEnd:     "Play the full game",
      replay:     "Run it again",
      scoreLabel: "Score",
      timeLabel:  "Time",
      endScore:   "Final score",
      gameOver:   "Crashed!",
      timeUp:     "Time's up!"
    },

    /* ---- TRIVERSE tunables ------------------------------------------------
       Everything below is read by the Game module (section 6). Distances are
       in PROGRESS pixels — the world coordinate the camera scrolls along.   */
    play: {

      /* SPEED. A run lasts twenty to forty seconds, so the ramp has to be over
         inside that: a slope tuned for a minute-long game just reads as a slow
         game. `speedMin` is set by how long a hazard stays readable — the arrow
         sees ~1000 design px of rope above it, which is 1.9s of warning at the
         opening speed and just under 1s flat out. */
      speedMin: 540,          // scroll speed at the first frame (px/s)
      speedMax: 1040,         // ...and once the ramp is over
      ramp:     18,           // seconds to reach top speed (danger ramps on distance)

      ahead:    1250,         // progress generated ahead of the camera
      edge:     84,           // keep the outer columns this far inside Layout
      dot:      27,           // rope dot spacing on a straight segment
      loopR:    88,           // radius of a loop segment
      loopClear: 76,          // room a loop lobe leaves between its far side and
                              // the rope it bulges towards
      sway:     26,           // how far the whole three-column grid may drift
                              // sideways, band to band (the gap never changes)
      calmP:    900,          // progress of plain rails and ribbons at the start
                              // of a run, before the figures kick in
      anchorUp: 170,          // the arrow's line, above Layout.bottom

      switchTime: 0.13,       // seconds of the lateral hop
      switchLock: 0.07,       // ...and the cooldown after it
      swipeMin:   26,         // design px of travel that count as a swipe

      pxPerM:   42,           // progress pixels per displayed metre
      mileStep: 240,          // metres between milestone glows

      lives:    3,
      invTime:  1.15,         // invulnerability after a crash
      multTime: 10,           // seconds of the x2 pickup

      // Difficulty is read off the DISTANCE travelled — the number the player
      // watches climb — and drives the mines: how often, how close together,
      // and how often they come two abreast. The gaps are PROGRESS, so they buy
      // less and less time as the scroll speeds up: they are set from the second
      // the player gets, not from the pixel count.
      diffFull:  560,         // metres to full difficulty
      hazardMin: 0.34,        // share of spawn slots that are hazards, at the
      hazardMax: 0.70,        // start of the run / at full difficulty
      gapFar:    420,         // progress between two hazards at the start...
      gapNear:   300,         // ...and at full difficulty, all ropes together:
                              // there is always a way through
      pairFrom:  0.16,        // difficulty at which mine pairs start showing up
      pairMax:   0.42,        // ...and their share of hazard slots at the top
      pairEvery: 2600,        // progress: never go longer than this without one
      pairAfter: 1.7,         // the calm after a pair, as a multiple of the gap
      hazardClear: 130,       // progress window a hazard keeps clear of a crossing
      hazardApart: 118,       // ...and the x distance that counts as "not crossing"
      /* The LEAD: no two ropes may cross in the stretch the player reads a
         hazard over. An input given while two ropes are still trading places
         lands on whichever is nearest at that instant — the right gesture on
         the wrong rope. So every hazard keeps this much calm IN FRONT of it:
         `leadTime` seconds of scroll at today's speed, never under `leadMin`. */
      leadTime:  0.5,
      leadMin:   280,

      /* THE JUMP — a flick up, or a tap on the arrow. It is measured in
         PROGRESS, not seconds, so it clears the same stretch at any speed:
         the longest hole plus a margin. */
      jumpLen:   380,         // progress covered in the air
      jumpLift:  34,          // design px the arrow rises at the top of the arc
      tapJump:   64,          // a tap this close to the arrow is a jump, not a hop
      coyote:    0.1,         // seconds over a hole before the fall: a late jump or hop still saves it
      fallTime:  0.75,        // the fall, before the arrow is set back on a rope

      // the bonuses' durations
      magnetTime: 6,
      ghostTime:  5
    },

    /* ---- the five biomes (web target) --------------------------------------
       The climb is cut into five stretches of six levels, and each is its own
       place: three rope colours, a ground and its particles, an arrow, and the
       one RULE the stretch teaches. The first is the game as it always was —
       the playable, a free round and the endless run all ride it.
       Chosen in lab/triverse-biomes.html, whose checker holds each palette to
       what the round needs read: the three ropes never pass for one another
       (the gates and the braids depend on it), each stands clear of its
       ground, and none wears a hazard's red or violet or the mega gem's gold.
       The grounds differ in HUE, not only in light — blue, green, slate, a
       violet dusk, a burnt brown — and the triads never repeat.
         ground   radial gradient, centre -> mid -> edge
         glow     [colour, strength] rising from the bottom edge, or null
         sky      the particle field: stars, shards, rain, comets, embers
         dot      the rope's dot: "dot" or "ring" (one sprite per colour)
         arrow    chevron, trident, dart, jet, prow
         figures  extra weights for the band generator, added to the shared
                  catalogue: the figures this stretch leans on
         rules    what the stretch adds to mines and voids: pad (a springboard
                  that throws the arrow onto the next rope), laser (a beam across
                  the three ropes, jumped), blink (a mine that sleeps and
                  wakes), break (a hole in a rope, jumped or fallen into),
                  comet (a hazard sliding down a rope), pendulum (a mine
                  swinging between two ropes), elec (one rope at a time
                  sparks, then goes live for two seconds)
         bonus    the pickups the stretch deals — each biome adds one         */
    biomes: [
      { key: "neon", music: { from: 17.05, length: 29.188 },   // A: the first full groove
        ropes: ["#3ce0ff", "#ff5ad4", "#a6ff3d"],
        ground: ["#141a44", "#080b22", "#03040c"], glow: null, sky: "stars", tint: "#ffffff",
        dot: "dot", arrow: "chevron", figures: [], rules: ["pad"],
        bonus: ["x2", "shield", "magnet"] },
      { key: "prism", music: { from: 48.16, length: 23.297 },  // B: the louder stretch, up to the break
        ropes: ["#5a8cff", "#ff6fd8", "#f4fbff"],
        ground: ["#0b3a1a", "#05200e", "#020a05"], glow: null, sky: "shards", tint: "#d8fff0",
        dot: "ring", arrow: "trident",
        figures: ["breath", "breath", "funnel", "ribbon", "plait", "shift"], rules: ["laser", "blink"],
        bonus: ["x2", "shield", "magnet", "ghost"] },
      { key: "storm", music: { from: 74.89, length: 31.026 },  // the breakdown and its build: the lull before the rain
        ropes: ["#4dffc3", "#8c9bff", "#ff4fe8"],
        ground: ["#2a3442", "#121820", "#06080c"], glow: null, sky: "rain", tint: "#cfe3ff",
        dot: "dot", arrow: "dart",
        figures: ["coil", "coil", "zigzag", "zigzag", "pulse", "jog", "funnel"], rules: ["break"],
        bonus: ["x2", "shield", "magnet", "ghost", "slow"] },
      { key: "comets", music: { from: 108.43, length: 31.026 }, // the drop out of the build, then its softer half
        ropes: ["#5ab4ff", "#ff8ae8", "#7dff8a"],
        ground: ["#1f1a2e", "#110e1c", "#05040a"], glow: ["#ff9d7a", 0.24], sky: "comets", tint: "#e8eeff",
        dot: "ring", arrow: "jet",
        figures: ["helix", "tornado", "breath", "breath", "lean", "butterfly"], rules: ["comet", "pendulum"],
        bonus: ["x2", "shield", "magnet", "ghost", "slow"] },
      { key: "fusion", music: { from: 139.53, length: 27.095 },// the finale, stopped before the fade-out
        ropes: ["#5a7bff", "#fff1dc", "#6dff9e"],
        ground: ["#2a1810", "#140b07", "#060302"], glow: ["#ff6a1c", 0.18], sky: "embers", tint: "#ffb347",
        dot: "dot", arrow: "prow",
        figures: ["cascade", "eight", "spring", "plait", "tornado"],
        rules: ["elec", "pad", "laser", "blink", "break", "comet", "pendulum"],
        bonus: ["x2", "shield", "magnet", "ghost", "slow"] }
    ],
    biomeFrom: [1, 7, 13, 19, 25],   // the LEVEL each biome opens on

    rule: {
      rate:       [0.2, 0.38],   // share of hazard slots a biome's rules take, first..last level of its stretch
      mixRate:    0.34,          // Fusion: what the six older rules share between them
      /* FUSION's own: one rope at a time is ELECTRIFIED. It sparks and blinks
         for `warn` seconds — harmless — then the whole rope is live for
         `live` seconds, being on it then is a crash, and the next one comes
         `gap` later. `grace` is the coyote time at the switch: a hop given in
         the first moments of the live phase still gets away clean. */
      elec:       { warn: 2.0, live: 2.0, grace: 0.3, gap: [1.6, 3.4] },
      cometSpeed: [150, 230],    // progress px/s a comet slides down its rope, on top of the scroll
      breakLen:   [140, 220],    // length of a hole, progress px — always shorter than play.jumpLen
      blinkPeriod: [1.5, 1.15],  // seconds of one sleep + wake of a blinking mine
      blinkOn:    0.55,          // ...the share of it the mine is armed
      swingPeriod: [2.0, 1.5],   // seconds of one swing of a pendulum, there and back
      airGems:    0.6            // chance a hole or a laser carries gems along the jump's arc
    }
  };

  /* ===================================================================
     2. ASSETS — embedded base64 data URIs only (no network requests ever).
     Generate entries with tools/lab/embed-asset.mjs. Prefer canvas drawing and
     WebAudio synth: every embedded byte counts against the 5 MB budget.
     =================================================================== */
  var ASSETS = {
    images: {
      // triverse.png -> the app icon shown on the intro (460x460, JPEG q80)
      logo: "data:image/jpeg;base64,"
    },
    sounds: {
      // The playable's bed: Neon's window of the track, the only stretch a
      // build with no levels plays (the web target ships the whole track,
      // web.music, and cuts it into the biomes' windows — CONFIG.biomes):
      //   ffmpeg -ss 16.08 -t 30.158 -i assets/audio/music/triverse.mp3 -ac 1 -ar 44100 -b:a 64k music.mp3
      music: "data:audio/mpeg;base64,"
      // No sfx clip here: every key the game plays is a role of the house kit,
      // mapped by `sfx` in manifest.json and injected by the builder.
    }
  };

  /* ===================================================================
     6. GAME — TRIVERSE: ride one of three living ropes and stay alive.

     Three dotted ropes of light run up the screen, generated forever. The
     arrow rides one of them on a fixed line near the bottom; the world scrolls
     past it, and a swipe (or a tap on either side of the arrow) hops it onto
     the neighbouring rope. Gems and power-ups pay, mines and voids cost — and
     the ropes cross, so the rope that looked safe a second ago may not be. The
     run ends when the third life goes.

     COORDINATES. Every curve is a closed-form function of the PROGRESS
     coordinate `p` (world pixels travelled). A segment answers { x, y } with
     y === p everywhere except inside a loop, which is exactly what lets a
     loop double back on itself without breaking the scroll:

       straight  x = x0
       curve     x = smoothstep(x0 -> x1)              flat tangent at both ends
       sine      x = c + amp * sin(2pi (p-p0)/wl + ph) whole periods only
       loop      x = x0 + dir*r*(1 - cos th)
                 y = p + r*sin th,   th = 2pi (p-p0)/span

     The loop is tangent to the vertical at both ends (dx/dth = 0 there), so
     it chains onto anything, and it genuinely crosses itself as long as
     span < 2pi*r. Its y wanders +/- r around p: that is the arrow dipping
     down the screen and coming back while it flies the curl.

     THE GRID AND THE FIGURES. The three ropes are NOT generated independently:
     that is what used to leave two of them running a hair apart, which reads as
     a mess and cannot be played. Instead the world is built one BAND at a time
     — a progress interval that emits exactly one segment per rope — and every
     band starts and ends with the three ropes parked on a three-column grid,
     `slotHalf()` apart. The gap is therefore a constant of the level, not a
     lottery, and a figure is free to braid through it because the player has
     seen where the ropes will land.

     A band is one of twenty figures: rails (three straights), ribbon / coil
     (in-phase sines, wide or zigzag-tight — the gap never moves), zigzag (the
     same with corners), pulse (flat, then a heartbeat kick), braid (two ropes
     half a turn apart around a shared centre: the DNA weave), plait (a real
     three-strand braid, the pairs trading in turn), scissors (the two outer
     ropes swinging through the middle one and out past it), helix (all three a
     third of a turn apart: the full vrille) and tornado (the same, tight and
     fast), breath (the trio squeezing in and opening back out), funnel (closing
     to a narrow corridor and holding it), lean (packed against one side), jog
     (the middle rope stepping half a column aside), shift (the columns
     re-dealt, ropes crossing on the way), and the loop family — one curl, a
     figure eight (two lobes, opposite ways), a spiral (two or three lobes the
     same way), the butterfly (both outer ropes curling in at once) and the
     cascade (one curl per rope, in turn, across the trio).

     Phase is the whole trick: a sine that starts a quarter turn in leaves its
     rope at the edge of its swing rather than at the centre, so two ropes can
     share a centre and still begin `2*amp` apart. Whole periods only, so a
     figure always hands the ropes back to the grid it borrowed them from.

     SCREEN. sy(y) = anchorY - (y - camP). The camera IS the arrow's progress,
     so the arrow sits exactly on anchorY at all times except inside a loop.
     =================================================================== */
  var Game = (function () {
    var TAU = Math.PI * 2;
    var T = CONFIG.play;

    // --- world -------------------------------------------------------------
    var paths = null;                 // the three ropes
    var items, trail;                 // pickups ahead, breadcrumbs behind

    // --- run state ---------------------------------------------------------
    var lane, prevLane, switchT, switchDir, switchLock;
    var camP, prevP, speed, runT;
    var score, pick, gems, chain, bestChain, loops;
    var lives, shield, mult, multT, invT;
    var dist, distShown, distT;
    var nextItemP, lastHazardP, lastPairP, nextMile, loopSeg, best, lastPop;
    var gates;                 // mine pairs, and the rope each one leaves open
    var arrowX, arrowY, arrowAng;

    // --- the band generator ------------------------------------------------
    var genP = 0;                     // progress the three ropes are built to
    var curX = [0, 0, 0];             // each rope's x at genP
    var slotRope = [0, 1, 2];         // slotRope[column] = the rope parked there
    var sway = 0;                     // lateral drift of the whole grid
    var onGrid = true;                // false right after a helix

    // --- cached per layout / per skin --------------------------------------
    var anchorY = 0, pMin = 0, pMax = 0, bgGrad = null, sparks = [];
    var dotDim = [], dotHot = [], dotKey = "";   // pre-rendered rope dots, one per colour
    var glowGrad = null, beamGrad = null;        // the biome's glow and prism beam
    // --- the biome (web target) ----------------------------------------------
    var BIO = CONFIG.biomes[0];       // the biome being played, set by applyLevel
    var RULES = [], RATE = 0, STEP = 0;   // its rules, their share of the slots, 0..1 through the stretch
    var elecOn = false, elec = null, elecWait = 0;   // Fusion's electrified rope, and the wait for the next
    // --- the jump, the fall, the timed pickups --------------------------------
    var jumpP = -1e9, wasAir = false, edgeT = 0;           // the jump's start, in progress
    var falling = false, fallT = 0, fallX = 0, fallP = 0, fallAng = 0;
    var magnetT = 0, ghostT = 0, rampT = 0;                // rampT drives the speed ramp: "slow" and a lost life reset it
    var flashT = 0, flashIn = 3, bolt = null, deco = [];   // the storm's lightning, the comets' sky

    /* Scratch points. Allocating inside the frame loop is what makes a mobile
       WebView stutter, so every curve evaluation writes into one of these. */
    var pa = { x: 0, y: 0 }, pb = { x: 0, y: 0 }, pc = { x: 0, y: 0 }, pp = { x: 0, y: 0 };
    var sa = { x: 0, y: 0 }, sb = { x: 0, y: 0 };          // generator-side scratch

    function ease(t) { return t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t); }
    function sy(y) { return anchorY - (y - camP); }

    /* ====================================================================
       THE ROPES — generation and evaluation
       ==================================================================== */

    // Kinds: 0 straight, 1 curve, 2 sine (phased), 3 loop.
    function segEval(s, p, out) {
      var t, u, th;
      if (s.k === 0) { out.x = s.x; out.y = p; }
      else if (s.k === 1) {
        t = (p - s.p0) / (s.p1 - s.p0);
        u = ease(t);
        out.x = s.x0 + (s.x1 - s.x0) * u; out.y = p;
      } else if (s.k === 2) {
        out.x = s.x + s.amp * Math.sin(TAU * (p - s.p0) / s.wl + s.ph); out.y = p;
      } else {
        th = TAU * (p - s.p0) / (s.p1 - s.p0);
        out.x = s.x + s.dir * s.r * (1 - Math.cos(th));
        out.y = p + s.r * Math.sin(th);
      }
    }

    // The segment covering `p` (clamped to the ends of the live window).
    function pathSeg(path, p) {
      var segs = path.segs, i;
      for (i = 0; i < segs.length; i++) if (p < segs[i].p1) return segs[i];
      return segs[segs.length - 1];
    }
    function pathPoint(path, p, out) { segEval(pathSeg(path, p), p, out); }
    function pathX(i, p) { pathPoint(paths[i], p, pc); return pc.x; }

    /* Dots are laid out every `step` progress pixels from the START of their
       segment, so they never crawl or shimmer as the camera moves. `step` is
       pre-divided by how much the curve stretches arc length, which keeps the
       rope evenly dotted through a sine and through a loop. */
    function dotStep(kind, a, b) {
      if (kind === 2) return T.dot / Math.sqrt(1 + (a * TAU / b) * (a * TAU / b) * 0.5);
      if (kind === 3) return T.dot * b / Math.sqrt(a * a + b * b);
      return T.dot;
    }

    /* --- the grid ---------------------------------------------------------
       Three columns, `slotHalf()` apart, the whole set drifting sideways by
       `sway` so it never looks ruled. Bands hand the ropes back to it, which is
       what makes the gap between two ropes a property of the level instead of a
       coincidence of two independent random walks. */
    function slotHalf() { return Layout.w * 0.5 - T.edge; }
    function slotX(s) { return Layout.cx + sway + (s - 1) * slotHalf(); }

    // Free space on one side of x before the play area runs out.
    function wallRoom(x, dir) {
      return dir > 0 ? (Layout.right - 26) - x : x - (Layout.left + 26);
    }

    // --- segment emitters. Each keeps curX[i] honest for the next band. -----
    function emitStraight(i, p0, p1) {
      paths[i].segs.push({ k: 0, p0: p0, p1: p1, x: curX[i], step: T.dot });
    }
    function emitCurve(i, p0, p1, x1) {
      paths[i].segs.push({ k: 1, p0: p0, p1: p1, x0: curX[i], x1: x1, step: T.dot * 0.86 });
      curX[i] = x1;
    }
    /* A phased sine — the figure engine. `ph` decides where on the swing the
       rope enters, so a caller can put two ropes on the SAME centre and still
       start them `2*amp` apart (they then weave through each other), or fan
       three of them a third of a turn apart. `n` whole periods, so x comes back
       to where it started and curX needs no update. */
    function emitSine(i, p0, wl, n, center, amp, ph) {
      paths[i].segs.push({ k: 2, p0: p0, p1: p0 + wl * n, x: center, amp: amp, wl: wl,
                           ph: ph, step: dotStep(2, Math.abs(amp), wl) });
    }
    /* One lobe. `tag` is set on the last lobe of a figure only — that is the
       one checkLoop pays out, so a figure eight scores once, not twice. */
    function emitLoop(i, p0, span, r, dir, n, tag) {
      paths[i].segs.push({ k: 3, p0: p0, p1: p0 + span, x: curX[i], r: r, dir: dir,
                           step: dotStep(3, r, span / TAU), n: n, tag: tag });
    }

    /* Move the trio onto the columns, `perm[column]` naming the rope that lands
       on each. The band is long enough that the widest move still eases in and
       out flat, so a swap reads as a lane change rather than a jolt. */
    function ferryTo(perm) {
      var i, len = 0;
      for (i = 0; i < 3; i++) len = Math.max(len, Math.abs(slotX(i) - curX[perm[i]]));
      len = clamp(250 + len * 1.05, 280, 660);
      for (i = 0; i < 3; i++) emitCurve(perm[i], genP, genP + len, slotX(i));
      slotRope = perm; onGrid = true; genP += len;
    }
    /* Fan back onto the grid the short way: leftmost rope to the left column,
       so nobody crosses anybody on a band that is only housekeeping. */
    function ferryHome() {
      var ord = [0, 1, 2];
      ord.sort(function (u, v) { return curX[u] - curX[v]; });
      ferryTo(ord);
    }

    /* The catalogue, as weights. Braids are the signature figure, the helix and
       the big loop tricks are rare enough to stay events. The second ten
       (plait onwards) came in 1.3.0; together they hold a little under half
       the draws, so a run still reads as the same game with more in it. */
    var FIGURES = ["rails", "rails", "ribbon", "ribbon", "coil", "coil",
                   "braid", "braid", "braid", "breath", "breath", "helix",
                   "shift", "shift", "shift", "loop", "loop", "eight", "spring",
                   "plait", "plait", "scissors", "scissors", "funnel", "lean",
                   "zigzag", "zigzag", "pulse", "pulse", "jog", "jog",
                   "tornado", "butterfly", "cascade"];
    var FIG = FIGURES;                // the catalogue plus the biome's own weights (applyLevel)
    var wantRails = false;            // a laser or a hole is waiting for a long straight...
    var pendingRule = null;           // ...and which one: it takes the next slot that reaches the rails
    // Re-dealings of the three columns, identity excluded: a shift must move.
    var SHIFTS = [[1, 0, 2], [0, 2, 1], [2, 1, 0], [1, 2, 0], [2, 0, 1]];

    // `long` is a run asked for by a laser or a hole, which only stand on straights.
    function pushRails(p0, long) {
      var len = long ? Rand.range(560, 700) : Rand.range(190, 330), i;
      for (i = 0; i < 3; i++) emitStraight(i, p0, p0 + len);
      genP = p0 + len;
    }

    /* Half a braid: the two ropes on columns `a` and `a + 1` trade places over
       half a period while the third holds its column. A sine leaves and lands
       on the extremes of its swing, so both ends are flat and the swap chains
       onto anything — several in a row, alternating pairs, are the plait. */
    function swapPair(a, len) {
      var ia = slotRope[a], ib = slotRope[a + 1], ic = slotRope[a === 0 ? 2 : 0],
          center = (slotX(a) + slotX(a + 1)) * 0.5, amp = (slotX(a + 1) - slotX(a)) * 0.5;
      emitSine(ia, genP, len * 2, 0.5, center, amp, -Math.PI / 2);   // column a -> a + 1
      emitSine(ib, genP, len * 2, 0.5, center, amp,  Math.PI / 2);   // column a + 1 -> a
      emitStraight(ic, genP, genP + len);
      curX[ia] = slotX(a + 1); curX[ib] = slotX(a);
      slotRope[a] = ib; slotRope[a + 1] = ia;
      genP += len;
    }

    /* Ease the trio onto `xs` (one x per column), hold them there for `hold`,
       and fan them back onto the grid in the same order: a figure made of three
       lane changes nobody has to make. */
    function holdAt(xs, hold) {
      var i, len = 0;
      for (i = 0; i < 3; i++) len = Math.max(len, Math.abs(xs[i] - curX[slotRope[i]]));
      len = clamp(220 + len * 1.05, 260, 560);
      for (i = 0; i < 3; i++) emitCurve(slotRope[i], genP, genP + len, xs[i]);
      genP += len;
      for (i = 0; i < 3; i++) emitStraight(slotRope[i], genP, genP + hold);
      genP += hold;
      ferryTo(slotRope.slice());
    }

    // One leg of an in-phase jink: every rope eases to its own `base` + `off`.
    function jinkTo(base, off, len) {
      var i;
      for (i = 0; i < 3; i++) emitCurve(i, genP, genP + len, base[i] + off);
      genP += len;
    }
    function holdAll(len) {
      var i;
      for (i = 0; i < 3; i++) emitStraight(i, genP, genP + len);
      genP += len;
    }

    function pushBand() {
      var p0 = genP, kind, i, a, b, ia, ib, ic, center, amp, wl, n, ph, xs, len,
          off, mid, li, gapL, gapR, r, dir, spans, total, q, k, base, order, tag;

      // A helix parks the ropes off the grid: spend the next band fanning them
      // back onto it, and nothing else.
      if (!onGrid) { ferryHome(); return; }
      if (wantRails) { wantRails = false; pushRails(p0, true); return; }

      kind = p0 < T.calmP ? Rand.pick(["rails", "ribbon", "shift"]) : Rand.pick(FIG);

      if (kind === "rails") { pushRails(p0); return; }

      if (kind === "shift") {
        // the grid itself slides a little, then the columns are re-dealt: the
        // ropes cross once, cleanly, in plain sight
        sway = clamp(sway + Rand.range(-T.sway, T.sway), -T.sway, T.sway);
        a = Rand.pick(SHIFTS);
        ferryTo([slotRope[a[0]], slotRope[a[1]], slotRope[a[2]]]);
        return;
      }

      if (kind === "ribbon" || kind === "coil") {
        // in phase: the three swing together, so a tight zigzag is exactly as
        // readable as a straight — the gap simply travels with them
        amp = Math.min(kind === "coil" ? 42 : 58,
                       Math.min(wallRoom(slotX(0), -1), wallRoom(slotX(2), 1)));
        if (amp < 22) { pushRails(p0); return; }          // pinned to the walls
        wl = kind === "coil" ? Rand.range(160, 220) : Rand.range(320, 460);
        n  = kind === "coil" ? Rand.int(3, 4) : Rand.int(1, 2);
        for (i = 0; i < 3; i++) emitSine(i, p0, wl, n, curX[i], amp, 0);
        genP = p0 + wl * n;
        return;
      }

      if (kind === "braid") {
        // THE DNA WEAVE. Two neighbours share a centre half a turn apart, so
        // each one starts on the other's column and they trade twice a period.
        a = Rand.chance(0.5) ? 0 : 1; b = a + 1;
        ia = slotRope[a]; ib = slotRope[b]; ic = slotRope[3 - a - b];
        center = (slotX(a) + slotX(b)) * 0.5;
        amp = (slotX(b) - slotX(a)) * 0.5;
        wl = Rand.range(320, 440); n = Rand.int(1, 2);
        emitSine(ia, p0, wl, n, center, amp, -Math.PI / 2);   // enters on column a
        emitSine(ib, p0, wl, n, center, amp,  Math.PI / 2);   // ...and on column b
        // the odd rope holds its column: a weave needs something still to read
        // against, and it is where a cautious player will sit it out
        emitStraight(ic, p0, p0 + wl * n);
        genP = p0 + wl * n;
        return;
      }

      if (kind === "helix" || kind === "tornado") {
        // THE VRILLE. All three around one centre, a third of a turn apart.
        // sin(-2pi/3) < sin(0) < sin(2pi/3), so handing the phases out left to
        // right means the run-in never tangles. The TORNADO is the same twist
        // pulled tight: a narrower column, a shorter turn, more of them.
        center = Layout.cx + sway;
        amp = slotHalf() * (kind === "tornado" ? 0.5 : 0.68);
        ph = [-TAU / 3, 0, TAU / 3];
        xs = []; len = 0;
        for (i = 0; i < 3; i++) xs.push(center + amp * Math.sin(ph[i]));
        for (i = 0; i < 3; i++) len = Math.max(len, Math.abs(xs[i] - curX[slotRope[i]]));
        len = clamp(240 + len * 1.05, 270, 620);
        for (i = 0; i < 3; i++) emitCurve(slotRope[i], p0, p0 + len, xs[i]);
        genP = p0 + len;
        if (kind === "tornado") { wl = Rand.range(190, 240); n = Rand.int(2, 3); }
        else { wl = Rand.range(330, 450); n = Rand.int(1, 2); }
        for (i = 0; i < 3; i++) emitSine(slotRope[i], genP, wl, n, center, amp, ph[i]);
        genP += wl * n;
        onGrid = false;                    // ends off the grid, by construction
        return;
      }

      if (kind === "breath") {
        /* The trio squeezes towards the middle and opens back out, in step.
           x_i = centre + off_i * f, f = mid + (1-mid) cos th, so f is 1 at both
           ends (the columns) and never dips under 2*mid-1 ~ 0.6 of the spread —
           it breathes, it does not collapse. */
        center = Layout.cx + sway;
        mid = Rand.range(0.80, 0.88);
        wl = Rand.range(320, 440); n = Rand.int(1, 2);
        for (i = 0; i < 3; i++) {
          off = slotX(i) - center;
          if (Math.abs(off) < 4) emitStraight(slotRope[i], p0, p0 + wl * n);
          else emitSine(slotRope[i], p0, wl, n, center + off * mid,
                        off * (1 - mid), Math.PI / 2);
        }
        genP = p0 + wl * n;
        return;
      }

      if (kind === "plait") {
        // THE PLAIT. A real three-strand braid: the left pair trades, then the
        // right pair, then the left again — every rope passes over the middle
        // in turn, which is how hair is braided.
        a = Rand.chance(0.5) ? 0 : 1;
        n = Rand.int(4, 6); len = Rand.range(170, 220);
        for (i = 0; i < n; i++) { swapPair(a, len); a = 1 - a; }
        return;
      }

      if (kind === "scissors") {
        // THE SCISSORS. The two outer ropes swing right through the middle one
        // and out past it, then come home: two blades crossing over a still
        // pin. All three meet at one point on the way, a crossing the hazard
        // rule keeps clear like any other; at the far end of the swing each
        // blade stands half a column past the pin, well clear of it.
        amp = slotHalf() * 0.75;
        wl = Rand.range(440, 560);
        emitSine(slotRope[0], p0, wl, 1, slotX(0) + amp, amp, -Math.PI / 2);
        emitSine(slotRope[2], p0, wl, 1, slotX(2) - amp, amp,  Math.PI / 2);
        emitStraight(slotRope[1], p0, p0 + wl);
        genP = p0 + wl;
        return;
      }

      if (kind === "funnel") {
        // THE FUNNEL. The trio closes in on the middle until the lanes are as
        // narrow as a hazard allows, runs that corridor, and opens back out.
        center = Layout.cx + sway;
        off = Math.max(T.hazardApart + 14, slotHalf() * 0.52);
        holdAt([center - off, center, center + off], Rand.range(220, 380));
        return;
      }

      if (kind === "lean") {
        // THE LEAN. The trio packs itself against one side — the outer column
        // there holds, the other two close in on it — leaving half the frame
        // empty, then stands back up.
        off = slotHalf() * 0.7;
        if (Rand.chance(0.5)) holdAt([slotX(0), slotX(0) + off, slotX(0) + off * 2], Rand.range(200, 340));
        else holdAt([slotX(2) - off * 2, slotX(2) - off, slotX(2)], Rand.range(200, 340));
        return;
      }

      if (kind === "zigzag" || kind === "pulse") {
        // In phase, like the ribbon, so the gap travels with the trio; the
        // swing is capped by the walls the same way.
        amp = Math.min(kind === "zigzag" ? 52 : 58, Math.min(wallRoom(slotX(0), -1), wallRoom(slotX(2), 1)));
        if (amp < 22) { pushRails(p0); return; }
        base = curX.slice();
        if (kind === "zigzag") {
          // THE ZIGZAG. A ribbon with corners: short eased legs, left, right,
          // left, each one flat at both ends so the turn reads as a corner.
          len = Rand.range(120, 160); n = Rand.int(2, 3);
          jinkTo(base, amp, len * 0.6);
          for (k = 0; k < n; k++) { jinkTo(base, -amp, len); jinkTo(base, amp, len); }
          jinkTo(base, 0, len * 0.6);
        } else {
          // THE PULSE. Flat, then a beat — a kick to one side and back through
          // the other, like a trace on a heart monitor. Two or three beats.
          dir = Rand.chance(0.5) ? 1 : -1; n = Rand.int(2, 3);
          for (k = 0; k < n; k++) {
            holdAll(Rand.range(110, 170));
            jinkTo(base, amp * dir, 80);
            jinkTo(base, -amp * 0.55 * dir, 110);
            jinkTo(base, 0, 80);
          }
        }
        return;
      }

      if (kind === "jog") {
        // THE JOG. The middle rope steps half a column aside, runs there, and
        // steps back: for a moment the trio is two ropes close and one far.
        li = slotRope[1];
        off = slotX(1) + (Rand.chance(0.5) ? 1 : -1) * slotHalf() * 0.5;
        len = Rand.range(220, 280); q = Rand.range(160, 280);
        emitCurve(li, p0, p0 + len, off);
        emitStraight(li, p0 + len, p0 + len + q);
        emitCurve(li, p0 + len + q, p0 + len * 2 + q, slotX(1));
        for (i = 0; i < 3; i++) if (i !== li) emitStraight(i, p0, p0 + len * 2 + q);
        genP = p0 + len * 2 + q;
        return;
      }

      if (kind === "butterfly") {
        // THE BUTTERFLY. Both outer ropes curl in towards the middle at once,
        // mirror images, one or two lobes each: two wings around a still body.
        // Each wing is sized like a loop — it may come close to the body,
        // never touch it — and the two never meet, since the body is between.
        a = slotRope[0]; b = slotRope[2]; ic = slotRope[1];
        r = Math.min(T.loopR, (Math.min(curX[ic] - curX[a], curX[b] - curX[ic]) - T.loopClear) * 0.5);
        if (r < 44) { pushRails(p0); return; }
        n = Rand.int(1, 2); spans = []; total = 0;
        for (i = 0; i < n; i++) { q = r * Rand.range(1.9, 2.5); spans.push(q); total += q; }
        emitStraight(ic, p0, p0 + total);
        q = p0;
        for (i = 0; i < n; i++) {
          tag = i === n - 1 ? "Butterfly!" : null;
          emitLoop(a, q, spans[i], r,  1, n, tag);
          emitLoop(b, q, spans[i], r, -1, n, tag);
          q += spans[i];
        }
        genP = p0 + total;
        return;
      }

      if (kind === "cascade") {
        // THE CASCADE. One curl per rope, in turn, across the trio: the outer
        // rope curls in, the middle one curls the same way, the far one curls
        // back — a wave of loops rolling across the lanes. One at a time, so
        // each curl only ever has its two still neighbours to keep clear of.
        order = Rand.chance(0.5) ? [0, 1, 2] : [2, 1, 0];
        dir = order[0] === 0 ? 1 : -1;
        r = Math.min(T.loopR, (slotHalf() - T.loopClear) * 0.5);
        if (r < 44) { pushRails(p0); return; }
        spans = []; total = 0;
        for (k = 0; k < 3; k++) { q = r * Rand.range(1.9, 2.4); spans.push(q); total += q; }
        q = p0;
        for (k = 0; k < 3; k++) {
          li = slotRope[order[k]];
          if (q > p0) emitStraight(li, p0, q);
          emitLoop(li, q, spans[k], r, k < 2 ? dir : -dir, 1, "Loop!");
          if (q + spans[k] < p0 + total) emitStraight(li, q + spans[k], p0 + total);
          q += spans[k];
        }
        genP = p0 + total;
        return;
      }

      /* THE LOOP FAMILY — one rope curls while the other two hold their column.
         A lobe reaches 2r sideways, so the radius is capped by the room between
         the rope and whatever it bulges towards, minus `loopClear`: the curl may
         come close to a neighbour, never touch it. An eight needs room on both
         sides, so it is always flown from the middle column. */
      li = kind === "loop" ? slotRope[Rand.int(0, 2)] : slotRope[1];
      gapL = wallRoom(curX[li], -1); gapR = wallRoom(curX[li], 1);
      for (i = 0; i < 3; i++) {
        if (i === li) continue;
        if (curX[i] < curX[li]) gapL = Math.min(gapL, curX[li] - curX[i]);
        else                    gapR = Math.min(gapR, curX[i] - curX[li]);
      }
      if (kind === "eight") {
        dir = Rand.chance(0.5) ? 1 : -1;
        r = Math.min(T.loopR, (Math.min(gapL, gapR) - T.loopClear) * 0.5);
      } else {
        dir = gapR >= gapL ? 1 : -1;
        r = Math.min(T.loopR, (Math.max(gapL, gapR) - T.loopClear) * 0.5);
      }
      if (r < 44) { pushRails(p0); return; }              // no room for a lobe
      n = kind === "loop" ? 1 : kind === "eight" ? 2 : Rand.int(2, 3);

      spans = []; total = 0;
      for (i = 0; i < n; i++) {
        // span < 2pi*r is what makes it a real loop; low in that range reads as
        // a round curl, high as a lazy S
        q = r * Rand.range(1.8, 2.7);
        spans.push(q); total += q;
      }
      for (i = 0; i < 3; i++) if (i !== li) emitStraight(i, p0, p0 + total);
      q = p0;
      for (i = 0; i < n; i++) {
        emitLoop(li, q, spans[i], r, kind === "eight" && (i % 2) ? -dir : dir, n,
                 i === n - 1 ? (n === 1 ? "Loop!" : kind === "eight" ? "Figure 8!" : "Spiral!")
                             : null);
        q += spans[i];
      }
      genP = p0 + total;
    }

    /* Generate up to `horizon` and drop what the camera has left behind. Bands
       always advance genP, so this cannot spin. */
    function buildAll(horizon) {
      var i, segs;
      while (genP < horizon) pushBand();
      for (i = 0; i < 3; i++) {
        segs = paths[i].segs;
        while (segs.length > 1 && segs[0].p1 < camP - 700) segs.shift();
      }
    }

    /* ====================================================================
       PICKUPS — gems pay, hazards cost
       ==================================================================== */

    function diff() { return Math.min(1, dist / T.diffFull); }
    function hazardChance() { return T.hazardMin + (T.hazardMax - T.hazardMin) * diff(); }
    function hazardGap()    { return T.gapFar - (T.gapFar - T.gapNear) * diff(); }
    function pairChance()   { return clamp((diff() - T.pairFrom) / (1 - T.pairFrom), 0, 1) * T.pairMax; }
    function otherLane() { return (lane + 1 + Rand.int(0, 1)) % 3; }
    function lead() { return Math.max(T.leadMin, speed * T.leadTime); }

    /* A hazard may never sit on a crossing. Two ropes running side by side is
       exactly where the player cannot tell WHICH one carries the mine, and a
       death you could not read is the one thing a playable must not do. So a
       candidate spot is only accepted when the other two ropes stay `hazardApart`
       design px away over a whole `hazardClear` window around it — the mine is
       then unmistakably on one rope, for long enough to be read and dodged.
       And IN FRONT of it, over the lead, no two ropes cross at all: that is
       where the dodge is given, and a hop given mid-crossing lands on the
       wrong rope (`calm`). */
    function crossingFree(idx, p) {
      return !elecBlocks(p) && freeRange(idx, p - T.hazardClear, p + T.hazardClear) && calm(p - lead(), p);
    }
    // True when rope `idx` is a plain straight over the whole stretch.
    function straight(idx, from, stop) {
      var segs = paths[idx].segs, i, s;
      for (i = 0; i < segs.length; i++) {
        s = segs[i];
        if (s.p1 <= from || s.p0 >= stop) continue;
        if (s.k !== 0) return false;
      }
      return true;
    }
    // One rope kept apart from the other two over a whole stretch.
    function freeRange(idx, from, stop) {
      var i, q;
      for (i = 0; i < 3; i++) {
        if (i === idx) continue;
        for (q = from; q <= stop; q += 20) {
          pathPoint(paths[idx], q, sa);
          pathPoint(paths[i], q, sb);
          if (Math.abs(sa.x - sb.x) < T.hazardApart) return false;
        }
      }
      return true;
    }
    // No two of the three ropes close together anywhere over a stretch.
    function calm(from, stop) {
      var q, x0, x1, x2;
      for (q = from; q <= stop; q += 20) {
        x0 = pathX(0, q); x1 = pathX(1, q); x2 = pathX(2, q);
        if (Math.abs(x0 - x1) < T.hazardApart || Math.abs(x0 - x2) < T.hazardApart ||
            Math.abs(x1 - x2) < T.hazardApart) return false;
      }
      return true;
    }
    /* Walk forward until a clear spot turns up: first the three ropes at `p`
       (the arrow's own rope first, that is what forces a jump), then a little
       further along. Returns the accepted { path, p } or null. */
    function hazardSpot(p, len) {
      var tries, i, order;
      // eight steps of 140: far enough to walk out past a whole braid or plait,
      // so the calm the lead asks for moves a hazard rather than deleting it
      for (tries = 0; tries < 8; tries++) {
        // The test has to read the real ropes: past `genP` a segment lookup
        // extrapolates the last curve, which is not the shape the generator will
        // actually commit. Growing them first costs nothing — bands are built
        // forward only, and never re-rolled.
        buildAll(p + (len || 0) + T.hazardClear + 100);
        order = Rand.chance(0.55) ? [lane, (lane + 1) % 3, (lane + 2) % 3]
                                  : [Rand.int(0, 2), lane, (lane + 1) % 3];
        for (i = 0; i < 3; i++) {
          if (len ? !elecBlocks(p) && straight(order[i], p - 80, p + len + 80) &&
                    freeRange(order[i], p - 60, p + len + 60) && calm(p - lead(), p)
                  : crossingFree(order[i], p)) return { path: order[i], p: p };
        }
        p += 140;
      }
      return null;
    }
    // The three ropes at progress `p`, left to right.
    function ropesAt(p) {
      var o = [0, 1, 2];
      o.sort(function (u, v) { return pathX(u, p) - pathX(v, p); });
      return o;
    }

    function pushMine(p, idx) {
      items.push({ p: p, path: idx, seed: Rand.range(0, TAU), type: "mine" });
    }

    /* TWO MINES ABREAST — the pressure beat the run builds towards. Both sit at
       the same progress, on two of the three ropes, so the wall can only be
       crossed through the third one.

       The crossing rule is turned around for a pair: it is the FREE rope that
       has to stand clear of the other two, because that is the thing the player
       must read from far away. The two mined ropes may run as close together as
       they like — either one kills, so there is nothing to tell apart. */
    function spawnPair(p) {
      var tries, i, free, order;
      for (tries = 0; tries < 8; tries++) {
        buildAll(p + T.hazardClear + 60);
        // Leave open a rope the arrow is NOT on: a wall you can ignore is not a
        // wall. Occasionally spare the current rope anyway, so a pair is never
        // a reflex the player can play blind.
        order = Rand.chance(0.78) ? [(lane + 1) % 3, (lane + 2) % 3, lane]
                                  : [lane, (lane + 1) % 3, (lane + 2) % 3];
        for (i = 0; i < 3; i++) {
          free = order[i];
          if (!crossingFree(free, p)) continue;
          pushMine(p, (free + 1) % 3);
          pushMine(p, (free + 2) % 3);
          gates.push({ p: p, free: free });
          lastHazardP = p; lastPairP = p;
          // a pair earns the player a breather: the next hazard is pushed back
          nextItemP = p + hazardGap() * T.pairAfter + Rand.range(60, 200);
          return true;
        }
        p += 150;
      }
      return false;
    }

    /* ---- the biome's rules ------------------------------------------------
       Each takes a hazard slot, so a stretch with a rule is not simply a
       stretch with more to dodge: the rule REPLACES some of the mines. */
    function lerpRule(r) { return r[0] + (r[1] - r[0]) * STEP; }
    /* A rule MET for the first time is named once per player, ever, by a
       notice whose line in the "!" log opens the rule's page of the guide
       (Notify.learn, which keeps the memory). It fires as the hazard is dealt,
       just above the frame, so the notice and the hazard arrive together.
       Only what the frame cannot say is named: the gesture a laser or a hole
       asks for, the sleep of a blinking mine, a comet's slide and the live
       rope's warning. A springboard and a pendulum read at a glance. */
    function met(kind) {
      if (kind === "laser")         Notify.learn("laser", "Laser", { sub: "Swipe up to jump the lasers" });
      else if (kind === "blink")    Notify.learn("blink", "Blinking mine", { sub: "Ride through a blinking mine while it sleeps" });
      else if (kind === "break")    Notify.learn("break", "Hole", { sub: "Swipe up to jump the holes" });
      else if (kind === "comet")    Notify.learn("comet", "Comet", { sub: "Comets slide down the ropes" });
      else if (kind === "elec")     Notify.learn("elec", "Live rope", { sub: "A rope goes live: get off it" });
    }

    function spawnRule(kind, p) {
      if (!dealRule(kind, p)) return false;
      met(kind);
      return true;
    }
    function dealRule(kind, p) {
      var tries, i, len, v, pm, s, o, k, dir, a, b;
      if (kind === "pad") {
        /* A SPRINGBOARD: the arrow that rides over it is thrown onto the next
           rope on the side it points to. It stands where that rope exists and
           both ropes are calm, and the rope it throws to is kept clear after. */
        for (tries = 0; tries < 4; tries++, p += 150) {
          buildAll(p + T.hazardClear + 60);
          o = ropesAt(p);
          k = Rand.int(0, 2);
          dir = k === 0 ? 1 : k === 2 ? -1 : (Rand.chance(0.5) ? 1 : -1);
          if (!crossingFree(o[k], p) || !freeRange(o[k + dir], p - 60, p + T.hazardClear)) continue;
          items.push({ p: p, path: o[k], dir: dir, type: "pad", seed: 0 });
          lastHazardP = p;
          nextItemP = p + Rand.range(hazardGap(), hazardGap() + 160);
          return true;
        }
        return false;
      }
      if (kind === "laser") {
        /* A LASER: a beam across the three ropes. No rope dodges it — only
           the jump does, and the jump is as long as the beam's warning is
           wide, so it asks for timing rather than a lane. It stands only
           across three STRAIGHT ropes, so the take-off and the landing are
           never on a curve; when none is in reach, the generator is asked for
           a long run of rails and the beam waits for it. Gems may ride the
           arc on one rope, for a jump taken where they are. */
        for (tries = 0; tries < 8; tries++, p += 140) {
          buildAll(p + T.jumpLen + 100);
          if (elecBlocks(p) || !straight(0, p - 220, p + 220) || !straight(1, p - 220, p + 220) ||
              !straight(2, p - 220, p + 220)) continue;
          items.push({ p: p, type: "laser", path: -1, seed: Rand.range(0, TAU) });
          if (Rand.chance(CONFIG.rule.airGems)) airGems(Rand.int(0, 2), p - T.jumpLen * 0.3, p + T.jumpLen * 0.3);
          lastHazardP = p;
          nextItemP = p + Rand.range(hazardGap() * 1.2, hazardGap() * 1.2 + 160);
          return true;
        }
        wantRails = true;
        return false;
      }
      if (kind === "blink") {
        /* A BLINKING MINE: armed, then asleep, on a beat. It can be dodged
           like any mine — or ridden through while it sleeps. */
        s = hazardSpot(p);
        if (!s) return false;
        items.push({ p: s.p, path: s.path, type: "blink", seed: Rand.range(0, TAU),
                     period: lerpRule(CONFIG.rule.blinkPeriod), ph: Rand.range(0, 1) });
        lastHazardP = s.p;
        nextItemP = s.p + Rand.range(hazardGap(), hazardGap() + 200);
        return true;
      }
      if (kind === "break") {
        /* A HOLE: a stretch of one rope with nothing under it. A mine is a
           point and asks for a hop; this is a LENGTH, and it asks for a jump —
           or a hop before it and a wait after. Kept clear of every crossing
           all along, and calm in front, like a mine. */
        len = Rand.range(CONFIG.rule.breakLen[0], CONFIG.rule.breakLen[1]);
        s = hazardSpot(p, len);
        if (!s) { wantRails = true; return false; }     // only on a straight: ask for one
        items.push({ p: s.p, path: s.path, len: len, type: "break", seed: 0, hit: false });
        if (Rand.chance(CONFIG.rule.airGems)) airGems(s.path, s.p, s.p + len);
        lastHazardP = s.p + len;
        nextItemP = s.p + len + Rand.range(hazardGap(), hazardGap() + 160);
        return true;
      }
      if (kind === "comet") {
        /* A COMET slides down its rope towards the arrow, faster than the
           scroll brings it. Where it will MEET the arrow (`pm`, at today's
           speed) must be clear of every other hazard, or the dodge it asks for
           has nowhere to land; and its rope must be calm there. */
        p = Math.max(p, camP + T.ahead - 120);
        v = lerpRule(CONFIG.rule.cometSpeed);
        pm = camP + (p - camP) * speed / (speed + v);
        if (elecBlocks(pm)) return false;
        for (i = 0; i < items.length; i++) {
          if (isHazard(items[i]) && Math.abs(items[i].p - pm) < 240) return false;
        }
        i = Rand.chance(0.5) ? lane : otherLane();
        if (!crossingFree(i, pm)) { i = (i + 1) % 3; if (!crossingFree(i, pm)) return false; }
        items.push({ p: p, path: i, type: "comet", v: v, seed: Rand.range(0, TAU), hit: false });
        lastHazardP = p;
        nextItemP = p + Rand.range(hazardGap(), hazardGap() + 200);
        return true;
      }
      if (kind === "pendulum") {
        /* A PENDULUM: a mine swinging between two neighbouring ropes, resting
           a beat on each. The third rope is always clear; the two it swings
           over are clear by turns, so it is read as a rhythm, not a place. */
        for (tries = 0; tries < 4; tries++, p += 150) {
          buildAll(p + T.hazardClear + 60);
          o = ropesAt(p);
          k = Rand.int(0, 1);
          a = o[k]; b = o[k + 1];
          if (!crossingFree(a, p) || !crossingFree(b, p)) continue;
          items.push({ p: p, path: a, b: b, type: "pendulum", seed: Rand.range(0, TAU),
                       w: TAU / lerpRule(CONFIG.rule.swingPeriod), ph: Rand.range(0, TAU) });
          lastHazardP = p;
          nextItemP = p + Rand.range(hazardGap(), hazardGap() + 200);
          return true;
        }
        return false;
      }
      return false;
    }

    function spawnSingle(p) {
      var spot = hazardSpot(p);
      if (!spot) return false;
      items.push({ p: spot.p, path: spot.path, seed: Rand.range(0, TAU),
                   type: Rand.chance(0.72) ? "mine" : "void" });
      lastHazardP = spot.p;
      nextItemP = spot.p + Rand.range(hazardGap(), hazardGap() + 200);
      return true;
    }

    function spawnItems(horizon) {
      var p, i, n, gap, lp, wantPair, rk;
      while (nextItemP < horizon) {
        p = nextItemP;
        // the biome's rule first: it takes a hazard slot when it fits one
        // A laser or a hole that found no straight asked for rails and WAITS for
        // them: it skips the dice, so the rails it asked for are not wasted.
        rk = RATE > 0 && !elecBlocks(p) ? (pendingRule || ruleKind()) : null;
        if (rk && p - lastHazardP > hazardGap() && (rk === pendingRule || Rand.chance(RATE))) {
          if (spawnRule(rk, p)) { if (rk === pendingRule) pendingRule = null; continue; }
          if (wantRails) pendingRule = rk;
        }
        if (!elecBlocks(p) && Rand.chance(hazardChance()) && p - lastHazardP > hazardGap()) {
          // A pair by chance, or because it has been too long since the last one
          // — "regularly" has to survive a bad roll of the dice.
          wantPair = diff() > T.pairFrom &&
                     (Rand.chance(pairChance()) || p - lastPairP > T.pairEvery);
          if (!(wantPair ? spawnPair(p) : spawnSingle(p))) {
            // everything ahead is a tangle of crossings: leave this slot empty
            nextItemP = p + Rand.range(200, 320);
          }

        } else if (Rand.chance(0.16)) {
          // a pickup, out of the ones this biome deals
          items.push({ p: p, path: Rand.int(0, 2), type: Rand.pick(BIO.bonus), seed: 0 });
          nextItemP = p + Rand.range(250, 380);

        } else if (Rand.chance(0.14)) {
          // THE LURE: one mega gem alone on a rope the arrow is not on — worth
          // a move, and placed where the move is a clean one
          lp = otherLane();
          if (crossingFree(lp, p)) items.push({ p: p, path: lp, type: "star", seed: 0 });
          nextItemP = p + Rand.range(220, 320);

        } else {
          // a run of gems, often on a rope the arrow is NOT on
          lp = Rand.chance(0.45) ? lane : otherLane();
          n = Rand.int(3, 5); gap = Rand.range(70, 92);   // the gems are big: keep them apart
          for (i = 0; i < n; i++) {
            items.push({ p: p + i * gap, path: lp, seed: 0,
                         type: (i === n - 1 && Rand.chance(0.22)) ? "star" : "gem" });
          }
          nextItemP = p + n * gap + Rand.range(130, 260);
        }
      }
    }

    // Where a pendulum's mine is now, between its two ropes, resting at each end.
    function pendX(it) {
      var xa = pathX(it.path, it.p), xb = pathX(it.b, it.p);
      return xa + (xb - xa) * (0.5 - 0.5 * Math.cos(runT * it.w + it.ph));
    }
    // A blinking mine is armed for the first `blinkOn` of its period.
    function blinkOn(it) { return ((runT / it.period + it.ph) % 1) < CONFIG.rule.blinkOn; }

    function resolveItems() {
      var i, it;
      for (i = items.length - 1; i >= 0; i--) {
        it = items[i];
        if (it.p + (it.len || 0) < camP - 400) { items.splice(i, 1); continue; }
        if (it.type === "comet" || it.type === "break") continue;   // see moveComets / checkHoles
        if (it.p > camP || it.p <= prevP) continue;      // not crossed this frame
        if (it.type === "laser") {                       // the beam: only the air is clear of it
          items.splice(i, 1);
          if (!airborne()) crash();
          continue;
        }
        if (it.type === "pendulum") {                    // wherever the swing has the mine right now
          items.splice(i, 1);
          if (Math.abs(pendX(it) - arrowX) < 62) crash();
          continue;
        }
        // the magnet pulls every gem on the ground in, whatever rope it is on
        if (magnetT > 0 && (it.type === "gem" || it.type === "star") && !it.air) {
          items.splice(i, 1); collect(it); continue;
        }
        if (it.path !== lane) continue;                  // it belongs to another rope
        if (it.air && !airborne()) continue;             // the jump's gems are the jump's
        items.splice(i, 1);
        if (it.type === "blink" && !blinkOn(it)) continue;   // ridden through while it slept
        if (it.type === "pad") { padThrow(it); continue; }
        collect(it);
      }
    }

    function gainScore(v) { pick += v; }

    function collect(it) {
      var x = arrowX, y = arrowY, col = paths[it.path >= 0 ? it.path : lane].color, g;

      if (it.type === "gem" || it.type === "star") {
        chain++;
        if (chain > bestChain) bestChain = chain;
        gems++;
        g = (it.type === "star" ? 120 : 15 + Math.min(chain, 12) * 3) * mult;
        gainScore(g);
        HUD.punch(it.type === "star" ? "#ffd43b" : col);
        Fx.burst(x, y, { color: [col, "#ffffff"], count: it.type === "star" ? 20 : 11,
                         speed: it.type === "star" ? 420 : 280, life: 0.42, size: 5 });
        if (it.type === "star") {
          Fx.ring(x, y, { from: 16, to: 130, color: "#ffd43b", width: 6, life: 0.38 });
          Pop.show("bonus", { word: "Mega gem", sub: "+" + g, at: "upperLeft" });
          Sound.clip("mega", 0.8);
        } else {
          // Gems arrive faster than a callout can be read: one pop per ~quarter
          // second, and the HUD punch plus the burst carry the ones in between.
          if (runT - lastPop > 0.24) {
            lastPop = runT;
            Pop.show("score", { word: "+" + g, at: { x: x, y: y - 116 }, cls: "pop-l" + lane });
          }
          // one sample, pitched by the chain: the run climbs as it grows
          Sound.clip("gem", 0.6, 1 + Math.min(chain, 14) * 0.045);
        }
        if (chain > 0 && chain % 6 === 0) {
          g = 50 * mult * (chain / 6);
          gainScore(g);
          Pop.show(chain >= 24 ? "ultra" : "combo", { word: Lang.t("Chain x") + chain, sub: "+" + g });
          Sound.clip("chain", 0.85, 1 + Math.min(chain, 24) * 0.008);
        }

      } else if (it.type === "x2") {
        mult = 2; multT = T.multTime;
        Pop.show("bonus", { word: "Score x2", sub: T.multTime + "s", at: "upperLeft" });
        Overlay.vignette("rgba(166,255,61,.8)", 1, 460);
        Fx.burst(x, y, { color: ["#a6ff3d", "#ffffff"], count: 18, speed: 340, life: 0.45 });
        Sound.clip("power", 0.8);

      } else if (it.type === "shield") {
        shield = true;
        Pop.show("bonus", { word: "Shield", sub: "One crash", at: "upperLeft" });
        Fx.ring(x, y, { from: 20, to: 120, color: "#8ffff2", width: 6, life: 0.4 });
        Sound.clip("power", 0.7, 1.22);

      } else if (it.type === "magnet") {
        magnetT = T.magnetTime;
        Pop.show("bonus", { word: "Magnet", sub: T.magnetTime + "s", at: "upperLeft" });
        Fx.ring(x, y, { from: 20, to: 150, color: "#ffd43b", width: 6, life: 0.45 });
        Sound.clip("magnet", 0.8);

      } else if (it.type === "ghost") {
        ghostT = T.ghostTime;
        Pop.show("bonus", { word: "Ghost", sub: T.ghostTime + "s", at: "upperLeft" });
        Fx.ring(x, y, { from: 20, to: 150, color: "#dfe6ff", width: 6, life: 0.45 });
        Sound.clip("ghost", 0.8);

      } else if (it.type === "slow") {
        // back to the speed the level opened on: the ramp starts over
        rampT = 0;
        Pop.show("bonus", { word: "Slow down", sub: "Start speed", at: "upperLeft" });
        Overlay.vignette("rgba(120,200,255,.75)", 1, 520);
        Fx.ring(x, y, { from: 20, to: 170, color: "#8fd0ff", width: 6, life: 0.5 });
        Sound.clip("slow", 0.8);

      } else if (it.type === "void") {
        // a ghost drifts through it; a shield takes it whole — score and chain
        if (ghostT > 0) return;
        if (shield) { shieldDown(); return; }
        g = Math.min(70 * mult, pick);
        pick -= g;
        chain = 0;
        Pop.show("alert", { word: "-" + g, sub: "Chain lost", cls: "pop-drain" });
        Fx.shake(7, 0.2);
        Fx.burst(x, y, { color: ["#a24bff", "#2b003f"], count: 16, speed: 300, life: 0.5 });
        Sound.clip("void", 0.75);

      } else {                                            // mine, or a blinking one awake
        crash();
      }
    }

    // The shield takes a hit WHOLE: no life, no score, no chain, no speed.
    function shieldDown() {
      shield = false; invT = 0.8;
      Fx.ring(arrowX, arrowY, { from: 18, to: 160, color: "#8ffff2", width: 7, life: 0.4 });
      Fx.shake(9, 0.24); Fx.flash("#8ffff2", 0.3);
      Pop.show("alert", { word: "Shield down" });
      Sound.clip("crash", 0.5, 1.45);        // the same impact, shrugged off
    }

    function crash() {
      var x = arrowX, y = arrowY;
      if (invT > 0 || falling) return;                    // still blinking: a free pass
      if (ghostT > 0) {                                   // a ghost passes through
        Fx.ring(x, y, { from: 14, to: 110, color: "#dfe6ff", width: 4, life: 0.3 });
        return;
      }
      if (shield) { shieldDown(); return; }
      chain = 0;
      Fx.burst(x, y, { color: ["#ff2d55", "#ffd43b", "#ffffff"], count: 26, speed: 460, life: 0.55, size: 6 });
      Fx.ring(x, y, { from: 18, to: 190, color: "#ff2d55", width: 8, life: 0.42 });

      lives--;
      rampT = 0;                    // a life lost sets the run back to the level's opening speed
      drawLives();
      Fx.shake(17, 0.4); Fx.flash("#ff2d55", 0.45); Fx.freeze(0.06);
      Overlay.vignette("rgba(255,45,85,.9)", 1, 620);
      Sound.clip("crash", 0.9);

      if (lives <= 0) { die(); return; }
      invT = T.invTime;
      Pop.show("streak", { word: lives === 1 ? Lang.t("Last life") : Lang.t("Crash!"),
                           sub: lives + (lives === 1 ? Lang.t(" life left") : Lang.t(" lives left")) });
    }

    /* Crossing a pair of mines through the one open rope is a skill beat, so it
       pays: without a reward the player only ever learns what NOT to do. */
    function checkGates() {
      var i, g, gain;
      for (i = gates.length - 1; i >= 0; i--) {
        g = gates[i];
        if (g.p < camP - 400) { gates.splice(i, 1); continue; }
        if (g.p > camP || g.p <= prevP) continue;      // not crossed this frame
        gates.splice(i, 1);
        if (lane !== g.free || invT > 0) continue;     // took the hit instead
        gain = 60 * mult;
        gainScore(gain);
        Fx.ring(arrowX, arrowY, { from: 26, to: 170, color: "#ffffff", width: 5, life: 0.36 });
        HUD.punch("#ffffff");
        Sound.clip("chain", 0.6, 1.28);
      }
    }

    /* ====================================================================
       THE JUMP, THE FALL AND THE SPRINGBOARD
       ==================================================================== */
    /* The jump is a stretch of PROGRESS in the air, from `jumpP`: the arrow
       follows its rope's x the whole way (a hop mid-air is allowed) and only
       the ground is out of reach — a hole, a laser and the jump's own gems
       are what it changes. Mines still stand too tall to clear. */
    function airborne() { return jumpP > -1e8 && camP - jumpP < T.jumpLen; }
    function jumpH() { return airborne() ? Math.sin(Math.PI * (camP - jumpP) / T.jumpLen) : 0; }
    function jump() {
      if (falling || airborne()) return;
      jumpP = camP;
      Sound.clip("jump", 0.7);
      Fx.burst(arrowX, arrowY + 10, { color: [paths[lane].color, "#ffffff"], count: 8, speed: 200,
                                      life: 0.3, angle: Math.PI / 2, spread: 1.2 });
    }
    // Back on the ground: a puff where it lands.
    function checkLanding() {
      if (wasAir && !airborne() && !falling) {
        Fx.ring(arrowX, arrowY, { from: 10, to: 60, color: paths[lane].color, width: 4, life: 0.22 });
      }
      wasAir = airborne();
    }

    /* A springboard throws the arrow onto the next rope on its side, in the
       air — the same arc as a jump, so it also clears what it lands beside. */
    function padThrow(it) {
      jumpP = camP; wasAir = true;
      switchLane(it.dir, true);
      Sound.clip("pad", 0.8);
      Fx.ring(arrowX, arrowY, { from: 16, to: 90, color: "#ffffff", width: 5, life: 0.26 });
    }

    /* A HOLE under a grounded arrow is a fall — after `coyote` seconds, so a
       jump or a hop given a hair late still counts. Only the jump saves you:
       the shield and the ghost do not hold anyone up. */
    function checkHoles(dt) {
      var i, it, over = null;
      if (falling) return;
      for (i = 0; i < items.length; i++) {
        it = items[i];
        if (it.type === "break" && it.path === lane && camP >= it.p && camP <= it.p + it.len) { over = it; break; }
      }
      if (!over || airborne()) { edgeT = 0; return; }
      edgeT += dt;
      if (edgeT > T.coyote) { edgeT = 0; fall(); }
    }
    function fall() {
      falling = true; fallT = 0;
      fallX = arrowX; fallP = camP + (anchorY - arrowY); fallAng = arrowAng;
      chain = 0;
      Sound.clip("fall", 0.85);
      Fx.burst(arrowX, arrowY, { color: [paths[lane].color, "#ffffff"], count: 14, speed: 160, life: 0.5 });
      Fx.shake(6, 0.25);
    }
    // The fall is over: a life gone, and the arrow set back on the nearest
    // rope that has ground under it, blinking.
    function land() {
      var i, best = -1, bd = 1e9, d, ok, j, it;
      falling = false;
      lives--;
      rampT = 0;                    // ...and so does a fall
      drawLives();
      Overlay.vignette("rgba(255,45,85,.85)", 1, 560);
      if (lives <= 0) { die(); return; }
      for (i = 0; i < 3; i++) {
        ok = true;
        for (j = 0; j < items.length; j++) {
          it = items[j];
          if (it.type === "break" && it.path === i && camP >= it.p - 40 && camP <= it.p + it.len) ok = false;
        }
        d = Math.abs(pathX(i, camP) - fallX);
        if (ok && d < bd) { bd = d; best = i; }
      }
      lane = prevLane = best < 0 ? lane : best;
      switchT = 1; invT = T.invTime;
      Fx.ring(pathX(lane, camP), anchorY, { from: 16, to: 120, color: paths[lane].color, width: 6, life: 0.4 });
      Pop.show("streak", { word: lives === 1 ? Lang.t("Last life") : Lang.t("Fell!"),
                           sub: lives + (lives === 1 ? Lang.t(" life left") : Lang.t(" lives left")) });
    }

    /* ====================================================================
       LOOPS — flying a whole figure is the run's showpiece
       ==================================================================== */
    /* A figure eight and a spiral are several lobes chained on one rope, and only
       the last one carries a `tag`: that is how a two-lobe figure pays once, for
       the whole trick, instead of twice for half of it. Leaving the rope part way
       drops the figure with no reward — flying it is the point. */
    function checkLoop() {
      var s = pathSeg(paths[lane], camP), g;
      if (s.k === 3 && camP > s.p0 + 6 && camP < s.p1) { loopSeg = s; return; }
      if (!loopSeg) return;
      if (camP >= loopSeg.p1 && loopSeg.tag) {
        g = 150 * loopSeg.n * mult;
        loops += loopSeg.n; gainScore(g);
        Pop.show("score", { word: loopSeg.tag, sub: "+" + g });
        Fx.ring(arrowX, arrowY, { from: 20, to: 200, color: "#ffd43b", width: 7, life: 0.45 });
        Fx.burst(arrowX, arrowY, { color: ["#ffd43b", "#ffffff"], count: 22, speed: 400, life: 0.5 });
        HUD.punch("#ffd43b");
        if (loopSeg.n > 1) Sound.clip("loop", 0.85, 0.9);
        else Sound.clip("loop", 0.85);
      }
      loopSeg = null;                                     // paid, or bailed out
    }

    /* ====================================================================
       INPUT — a swipe, or a tap on either side of the arrow
       ==================================================================== */
    var gest = null;

    function switchLane(dir, forced) {
      var curX, i, x, d, bi = -1, bd = 1e9;
      if (falling || (switchLock > 0 && !forced)) return;
      curX = pathX(lane, camP);
      for (i = 0; i < 3; i++) {
        if (i === lane) continue;
        x = pathX(i, camP);
        d = (x - curX) * dir;                             // > 0 = in the swipe direction
        if (d > 12 && d < bd) { bd = d; bi = i; }
      }
      if (bi < 0) {                                       // nothing that way: nudge
        Fx.shake(3, 0.1);
        Sound.clip("swipe", 0.3, 0.62);        // the flick, muffled: nothing there
        return;
      }
      prevLane = lane; lane = bi;
      switchT = 0; switchDir = dir; switchLock = T.switchLock;
      Fx.burst(arrowX, arrowY, { color: [paths[prevLane].color, "#ffffff"], count: 9,
                                 speed: 260, life: 0.3, angle: dir > 0 ? Math.PI : 0, spread: 1.7 });
      Fx.ring(arrowX, arrowY, { from: 14, to: 66, color: paths[lane].color, width: 4, life: 0.24 });
      if (dir > 0) Sound.clip("swipe", 0.6, 1.08);   // pitch tells the direction
      else Sound.clip("swipe", 0.6, 0.93);
    }

    /* A flick UP is the jump; a flick sideways is a hop. Up wins only when it
       clearly is up (1.2 times the sideways travel), so a sloppy sideways
       flick is never read as a jump. */
    function isUp(dx, dy) { return -dy > T.swipeMin && -dy > Math.abs(dx) * 1.2; }
    function onDown(p) { gest = { x: p.x, y: p.y, done: false }; }
    function onMove(p) {
      if (!gest || gest.done) return;
      var dx = p.x - gest.x, dy = p.y - gest.y;
      if (isUp(dx, dy)) { gest.done = true; jump(); return; }
      if (Math.abs(dx) > T.swipeMin) { gest.done = true; switchLane(dx > 0 ? 1 : -1); }
    }
    function onUp(p) {
      if (!gest) return;
      if (!gest.done) {
        var dx = p.x - gest.x, dy = p.y - gest.y;
        // A short gesture is a tap: on the arrow it is the jump, beside it
        // it means "go to the side I tapped".
        if (isUp(dx, dy)) jump();
        else if (Math.abs(dx) > T.swipeMin) switchLane(dx > 0 ? 1 : -1);
        else if (Math.abs(p.x - arrowX) < T.tapJump && Math.abs(p.y - arrowY) < T.tapJump * 1.5) jump();
        else switchLane(p.x >= arrowX ? 1 : -1);
      }
      gest = null;
    }

    /* ====================================================================
       FRAME
       ==================================================================== */
    function reset() {
      var i;
      best = Store.get("bestScore", 0);
      metrics();
      buildDots();
      /* THE BED: the biome's window of the track. Asking for the section
         already playing does nothing, so a replay never restarts it. Without a
         level (the playable, a free round, the endless run) the bed is the
         whole of what the build ships — the playable embeds only Neon's. */
      Music.play(CONFIG.level ? BIO.music : null);
      paintPalette();
      elecOn = RULES.indexOf("elec") >= 0; elec = null; elecWait = CONFIG.rule.elec.gap[1];
      flashT = 0; flashIn = 3; bolt = null; deco = [];
      jumpP = -1e9; wasAir = false; edgeT = 0; falling = false; fallT = 0;
      magnetT = 0; ghostT = 0; rampT = 0;

      camP = 0; prevP = 0; runT = 0; speed = T.speedMin;
      score = 0; pick = 0; gems = 0; chain = 0; bestChain = 0; loops = 0;
      lives = T.lives; shield = false; mult = 1; multT = 0; invT = 0;
      dist = 0; distShown = 0; distT = 0;
      lane = 1; prevLane = 1; switchT = 1; switchDir = 0; switchLock = 0;
      loopSeg = null; gest = null; lastPop = -1;
      items = []; trail = []; gates = [];
      // the opening second stays empty: at this speed an item at 560 would be on
      // the arrow before the player has read the three ropes
      nextItemP = 760; lastHazardP = 0; lastPairP = 0; nextMile = T.mileStep;

      // the run opens with the three ropes parked on the grid, dead straight, so
      // the first second says "three lanes, pick one" and nothing else
      sway = 0; onGrid = true; slotRope = [0, 1, 2]; genP = 340; wantRails = false; pendingRule = null;
      curX = [slotX(0), slotX(1), slotX(2)];
      paths = [];
      for (i = 0; i < 3; i++) {
        paths.push({ idx: i, color: BIO.ropes[i],
                     segs: [{ k: 0, p0: -800, p1: 340, x: curX[i], step: T.dot }] });
      }
      buildAll(T.ahead);
      pMin = anchorY - view.h - 220; pMax = anchorY + 220;

      arrowX = curX[1]; arrowY = anchorY; arrowAng = -Math.PI / 2;
      HUD.setScoreNow(0);
      HUD.setLeft("0 m", "Dist");
      drawLives();
      Fx.reset();
    }

    /* The callouts burn in the colour of the rope that earned them, and the
       ropes are the biome's: the SKIN reads --rp0..2 (fill), --rg0..2 (glow)
       and --ri0..2 (ink), defaulting to Neon's own three. */
    function paintPalette() {
      var st = document.documentElement.style, i, c;
      for (i = 0; i < 3; i++) {
        c = BIO.ropes[i];
        st.setProperty("--rp" + i, c);
        st.setProperty("--rg" + i, rgba(c, 0.75));
        st.setProperty("--ri" + i, shade(c, 0.85));
      }
    }
    // `hex` taken `k` of the way to black, as a hex colour.
    function shade(hex, k) {
      var n = parseInt(hex.slice(1), 16), r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
      r = Math.round(r * (1 - k)); g = Math.round(g * (1 - k)); b = Math.round(b * (1 - k));
      return "#" + ((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1);
    }

    function drawLives() {
      var s = "", i;
      for (i = 0; i < T.lives; i++) s += i < lives ? "♥" : "·";
      HUD.setRight(s, "Lives", lives <= 1 ? "warn" : "");
    }

    function updateArrow() {
      var e = ease(switchT), x, y, ang;
      pathPoint(paths[lane], camP, pa);
      x = pa.x; y = pa.y;
      if (switchT < 1) {
        pathPoint(paths[prevLane], camP, pb);
        x = pb.x + (pa.x - pb.x) * e;
        y = pb.y + (pa.y - pb.y) * e;
      }
      // heading = the tangent of the rope, in screen space (y is flipped)
      pathPoint(paths[lane], camP + 7, pb);
      pathPoint(paths[lane], camP - 7, pc);
      ang = Math.atan2(-(pb.y - pc.y), pb.x - pc.x);
      if (switchT < 1) ang += switchDir * 0.5 * Math.sin(Math.PI * switchT);   // lean into the hop
      arrowX = x; arrowY = sy(y); arrowAng = ang;

      trail.push({ x: x, y: y });
      if (trail.length > 18) trail.shift();
    }

    /* A comet's progress runs BACKWARDS, towards the camera: when it reaches
       the arrow's line it either finds the arrow on its rope or slides past. */
    function moveComets(dt) {
      var i, it;
      for (i = items.length - 1; i >= 0; i--) {
        it = items[i];
        if (it.type !== "comet") continue;
        it.p -= it.v * dt;
        if (it.p < camP - 400) { items.splice(i, 1); continue; }
        if (!it.hit && it.p <= camP) { it.hit = true; if (it.path === lane) crash(); }
      }
    }

    /* FUSION's rule: ONE ROPE GOES LIVE. It is scheduled in PROGRESS, like
       every hazard — `p0` where it goes live, `p1` where it dies — so the
       spawner can keep the way out open: an event only starts when the two
       other ropes are clear of hazards over the whole live stretch and the
       ropes are not crossing where the hop off it has to be given, and while
       it runs no new hazard is placed there (`elecBlocks`). One crash per
       event: after it the arrow blinks and has time to leave. */
    function elecBlocks(p) { return !!elec && p > elec.p0 - 200 && p < elec.p1 + 100; }
    function hazardOn(r, from, stop) {
      var i, it;
      for (i = 0; i < items.length; i++) {
        it = items[i];
        if (!isHazard(it) || it.type === "laser" || it.type === "comet") continue;
        if (it.p + (it.len || 0) < from || it.p > stop) continue;
        if (it.type === "pendulum" || it.path !== r) return true;   // a pendulum always spans another rope
      }
      return false;
    }
    function updateElec(dt) {
      var C = CONFIG.rule.elec, w0, w1, order, i;
      if (!elecOn) return;
      if (elec) {
        if (camP > elec.p1) { elec = null; elecWait = Rand.range(C.gap[0], C.gap[1]); return; }
        if (!elec.live && camP >= elec.p0) {
          elec.live = true; elec.liveT = 0;
          Sound.clip("zap", 0.7);
          Fx.shake(6, 0.25); Fx.flash("#bfe9ff", 0.18);
        }
        if (elec.live) elec.liveT += dt;
        if (elec.live && elec.liveT > C.grace && !elec.hit && lane === elec.rope && !airborne() && invT <= 0) {
          elec.hit = true;
          crash();
        }
        return;
      }
      elecWait -= dt;
      if (elecWait > 0) return;
      w0 = camP + speed * C.warn;
      w1 = w0 + speed * C.live * 1.1;
      if (!calm(w0 - lead(), w0 + 100)) return;           // not where the hop off is given: next frame
      order = Rand.chance(0.55) ? [lane, (lane + 1) % 3, (lane + 2) % 3] : [(lane + 1) % 3, (lane + 2) % 3, lane];
      for (i = 0; i < 3; i++) {
        if (hazardOn(order[i], w0 - 200, w1 + 100)) continue;
        elec = { rope: order[i], start: camP, p0: w0, p1: w1, live: false, liveT: 0, hit: false };
        met("elec");
        Sound.clip("zap", 0.3, 1.7);
        return;
      }
    }

    // The storm's lightning and the comets' own sky: decoration on a timer.
    function updateSky(dt) {
      var i, d, sp, x, y;
      if (BIO.sky === "rain") {
        flashT = Math.max(0, flashT - dt);
        flashIn -= dt;
        if (flashIn <= 0) {
          flashIn = Rand.range(3, 7); flashT = 0.38; bolt = [];
          x = Rand.range(120, view.w - 120); y = -20;
          while (y < view.h * Rand.range(0.3, 0.5)) { bolt.push(x, y); y += Rand.range(40, 80); x += Rand.range(-46, 46); }
        }
      } else if (BIO.sky === "comets") {
        for (i = deco.length - 1; i >= 0; i--) {
          d = deco[i]; d.x += d.vx * dt; d.y += d.vy * dt;
          if (d.y > view.h + 200 || d.x < -300) deco.splice(i, 1);
        }
        if (deco.length < 2 && Rand.chance(dt * 0.9)) {
          sp = Rand.range(520, 900);
          deco.push({ x: Rand.range(300, view.w + 180), y: Rand.range(-160, view.h * 0.3),
                      vx: -sp * 0.62, vy: sp * 0.78, len: Rand.range(160, 260) });
        }
      }
    }

    function update(dt) {
      var m;
      runT += dt; rampT += dt;
      speed = T.speedMin + (T.speedMax - T.speedMin) * Math.min(1, rampT / T.ramp);
      if (falling) speed *= 0.35;                         // the world holds its breath over the fall
      prevP = camP;
      camP += speed * dt;

      // the visible progress window, plus a margin for the loops' wander
      pMin = camP + anchorY - view.h - 220;
      pMax = camP + anchorY + 220;

      buildAll(camP + T.ahead);
      spawnItems(camP + T.ahead - 120);

      if (switchT < 1) switchT = Math.min(1, switchT + dt / T.switchTime);
      if (switchLock > 0) switchLock -= dt;
      if (invT > 0) invT -= dt;
      if (multT > 0) {
        multT -= dt;
        if (multT <= 0) mult = 1;
      }
      /* Only the ghost running out is said: mines bite again, which changes
         what the player must do now. The x2 and the magnet just stop. */
      if (magnetT > 0) magnetT -= dt;
      if (ghostT > 0)  { ghostT -= dt;  if (ghostT <= 0)  Notify.say("Ghost over", { icon: "hourglass", guide: "ghost" }); }

      updateSky(dt);
      if (falling) {                                      // nothing touches an arrow in the void
        fallT += dt;
        moveComets(dt);
        if (fallT >= T.fallTime) land();
      } else {
        updateArrow();
        checkLanding();
        moveComets(dt);
        resolveItems();
        checkHoles(dt);
        checkGates();
        checkLoop();
        updateElec(dt);
      }

      dist = camP / T.pxPerM;
      score = pick + Math.floor(dist);
      HUD.setScore(score);

      distT -= dt;
      m = Math.floor(dist);
      if (distT <= 0 && m !== distShown) { distShown = m; distT = 0.14; HUD.setLeft(m + " m", "Dist"); }

      if (dist >= nextMile) {
        nextMile += T.mileStep;
        // the run speeding up is felt, not said: a glow and a sound
        Overlay.vignette(rgba(paths[lane].color, 0.75), 1, 420);
        Sound.clip("chain", 0.7, 0.8);
      }
    }

    function die() {
      var d = Math.floor(dist), sc = pick + d;
      // Scaled with the scroll speed: the same run earns the same stars it used
      // to, it just gets there sooner.
      var st = sc >= 4700 ? 3 : sc >= 2200 ? 2 : 1;
      endRound({
        title: st === 3 ? Lang.t("Legend run!") : st === 2 ? Lang.t("Great run!") : CONFIG.copy.gameOver,
        variant: st === 3 ? "perfect" : st === 2 ? "win" : "",
        score: sc,
        // A level's objective is a distance: the metres, not the metres plus
        // the gems picked up along them (web target only — see levelProgress).
        levelScore: d,
        stars: st,
        rows: [
          { label: "Distance (m)", value: d },
          { label: "Gems", value: gems },
          { label: "Best chain", value: bestChain, grade: "accent" },
          { label: "Best score", value: Math.max(sc, best), grade: "gold" }
        ]
      });
    }

    /* ====================================================================
       RENDER
       ==================================================================== */

    // One sprite per rope colour: the glow and the core in a single draw, so a
    // rope costs one drawImage per dot and never touches shadowBlur. A biome's
    // `dot` is a filled dot or a hollow ring — the same cost either way.
    function dotSprite(color, hot, kind) {
      var s = hot ? 46 : 38, c = document.createElement("canvas"), k, h = s * 0.5, g;
      c.width = s; c.height = s;
      k = c.getContext("2d");
      g = k.createRadialGradient(h, h, 0, h, h, h);
      g.addColorStop(0, rgba(color, hot ? 0.55 : 0.26));
      g.addColorStop(0.45, rgba(color, hot ? 0.2 : 0.08));
      g.addColorStop(1, rgba(color, 0));
      k.fillStyle = g; k.fillRect(0, 0, s, s);
      if (kind === "ring") {
        k.strokeStyle = color; k.lineWidth = hot ? 3.6 : 3;
        k.beginPath(); k.arc(h, h, hot ? 8.5 : 6.5, 0, TAU); k.stroke();
        if (hot) { k.fillStyle = "#ffffff"; k.beginPath(); k.arc(h, h, 2.6, 0, TAU); k.fill(); }
        return c;
      }
      k.fillStyle = color;
      k.beginPath(); k.arc(h, h, hot ? 7.5 : 5.2, 0, TAU); k.fill();
      if (hot) {
        k.fillStyle = "rgba(255,255,255,.92)";
        k.beginPath(); k.arc(h, h, 3.4, 0, TAU); k.fill();
      }
      return c;
    }
    // Rebuilt when the biome changes, never once per round.
    function buildDots() {
      var i, key = BIO.key + BIO.dot;
      if (key === dotKey) return;
      for (i = 0; i < dotDim.length; i++) { freeCanvas(dotDim[i]); freeCanvas(dotHot[i]); }
      dotDim = []; dotHot = []; dotKey = key;
      for (i = 0; i < 3; i++) {
        dotDim.push(dotSprite(BIO.ropes[i], false, BIO.dot));
        dotHot.push(dotSprite(BIO.ropes[i], true, BIO.dot));
      }
    }

    function metrics() {
      var g = BIO.ground;
      anchorY = Layout.bottom - T.anchorUp;
      bgGrad = ctx.createRadialGradient(view.w * 0.5, view.h * 0.3, 40, view.w * 0.5, view.h * 0.42, view.h * 0.95);
      bgGrad.addColorStop(0, g[0]);
      bgGrad.addColorStop(0.55, g[1]);
      bgGrad.addColorStop(1, g[2]);
      glowGrad = null;
      if (BIO.glow) {
        glowGrad = ctx.createRadialGradient(view.w * 0.5, view.h * 1.08, 20, view.w * 0.5, view.h * 1.08, view.h * 0.75);
        glowGrad.addColorStop(0, rgba(BIO.glow[0], BIO.glow[1]));
        glowGrad.addColorStop(1, rgba(BIO.glow[0], 0));
      }
      // the prism's light beam, built once in its own frame and drawn rotated
      beamGrad = ctx.createLinearGradient(-90, 0, 90, 0);
      beamGrad.addColorStop(0, rgba(BIO.tint, 0));
      beamGrad.addColorStop(0.5, rgba(BIO.tint, 0.07));
      beamGrad.addColorStop(1, rgba(BIO.tint, 0));
      buildSparks();
    }

    /* The sky: what the biome's ground carries. Every field scrolls off camP
       with its own parallax and wraps on the frame height. Neon's is the one
       the game always had — far stars for depth, near streaks for speed. */
    var SKY_COUNT = { stars: 70, shards: 34, rain: 90, comets: 44, embers: 60 };
    function buildSparks() {
      var i, star, n = SKY_COUNT[BIO.sky] || 70;
      sparks = [];
      for (i = 0; i < n; i++) {
        star = i < n * 0.68;
        sparks.push({
          x: Rand.range(0, view.w),
          y: Rand.range(0, view.h + 80),
          w: star ? Rand.range(2, 3.4) : 2,
          h: star ? Rand.range(2, 3.4) : Rand.range(40, 110),
          par: star ? Rand.range(0.16, 0.42) : Rand.range(0.85, 1.3),
          a: star ? Rand.range(0.25, 0.6) : Rand.range(0.06, 0.14),
          // prism shards keep out of red, violet and pink — the hazards' hues
          hue: Rand.pick([Rand.range(40, 70), Rand.range(120, 170), Rand.range(185, 250)]),
          r: Rand.range(5, 13), rot: Rand.range(0, TAU), spin: Rand.range(-0.8, 0.8),
          v: Rand.range(900, 1500), len: Rand.range(30, 70),
          rise: Rand.range(60, 150), ph: Rand.range(0, TAU), f: Rand.range(4, 11)
        });
      }
    }

    function drawSparks() {
      var span = view.h + 80, i, s, y, x, k, sky = BIO.sky;
      if (glowGrad) { ctx.fillStyle = glowGrad; ctx.fillRect(0, 0, view.w, view.h); }
      if (sky === "stars" || sky === "comets") {
        ctx.fillStyle = BIO.tint;
        for (i = 0; i < sparks.length; i++) {
          s = sparks[i];
          if (sky === "comets" && s.h > 4) continue;          // a still sky: no speed streaks
          y = (s.y + camP * s.par) % span;
          if (y < 0) y += span;
          ctx.globalAlpha = s.a;
          ctx.fillRect(s.x, y - 40, s.w, s.h);
        }
        if (sky === "comets") drawDecoComets();
      } else if (sky === "shards") {
        ctx.fillStyle = beamGrad;
        for (i = 0; i < 3; i++) {
          ctx.save();
          ctx.translate(((i * 290 + runT * 14) % (view.w + 500)) - 250, view.h * 0.5);
          ctx.rotate(-0.36);
          ctx.fillRect(-90, -view.h, 180, view.h * 2);
          ctx.restore();
        }
        for (i = 0; i < sparks.length; i++) {
          s = sparks[i];
          y = (s.y + camP * s.par * 0.6) % span;
          if (y < 0) y += span;
          ctx.save(); ctx.translate(s.x, y - 40); ctx.rotate(s.rot + runT * s.spin);
          ctx.globalAlpha = s.a * 0.7;
          ctx.fillStyle = "hsl(" + Math.round(s.hue) + ",90%,72%)";
          ctx.beginPath(); ctx.moveTo(0, -s.r); ctx.lineTo(s.r * 0.4, 0); ctx.lineTo(0, s.r); ctx.lineTo(-s.r * 0.4, 0);
          ctx.closePath(); ctx.fill();
          ctx.restore();
        }
      } else if (sky === "rain") {
        if (flashT > 0) {
          k = flashT / 0.38;
          ctx.globalAlpha = 0.1 * k; ctx.fillStyle = "#ffffff"; ctx.fillRect(0, 0, view.w, view.h);
          if (bolt) {
            ctx.strokeStyle = BIO.tint; ctx.lineJoin = "round"; ctx.lineCap = "round";
            ctx.beginPath(); ctx.moveTo(bolt[0], bolt[1]);
            for (i = 2; i < bolt.length; i += 2) ctx.lineTo(bolt[i], bolt[i + 1]);
            ctx.globalAlpha = 0.12 * k; ctx.lineWidth = 14; ctx.stroke();
            ctx.globalAlpha = 0.5 * k; ctx.lineWidth = 4; ctx.stroke();
          }
        }
        // one path for the whole shower: a stroke per drop would be ninety
        ctx.strokeStyle = BIO.tint; ctx.lineWidth = 2; ctx.lineCap = "round"; ctx.globalAlpha = 0.2;
        ctx.beginPath();
        for (i = 0; i < sparks.length; i++) {
          s = sparks[i];
          y = (s.y + camP * s.par * 0.5 + runT * s.v * 0.5) % span;
          if (y < 0) y += span;
          ctx.moveTo(s.x, y - 40); ctx.lineTo(s.x - s.len * 0.22, y - 40 + s.len);
        }
        ctx.stroke();
      } else if (sky === "embers") {
        ctx.fillStyle = BIO.tint;
        for (i = 0; i < sparks.length; i++) {
          s = sparks[i];
          y = (s.y + camP * 0.12 - runT * s.rise) % span;
          if (y < 0) y += span;
          x = s.x + Math.sin(runT * 1.3 + s.ph) * 14;
          ctx.globalAlpha = s.a * (0.55 + 0.45 * Math.sin(runT * s.f + s.ph));
          ctx.beginPath(); ctx.arc(x, y - 40, s.w * 0.8, 0, TAU); ctx.fill();
        }
      }
      ctx.globalAlpha = 1;
    }
    // Far comets crossing the comets' sky: thin, pale and diagonal, so they are
    // never read as the red ones sliding down the ropes.
    function drawDecoComets() {
      var i, d, g, tx, ty;
      ctx.globalAlpha = 1; ctx.lineWidth = 3; ctx.lineCap = "round";
      for (i = 0; i < deco.length; i++) {
        d = deco[i]; tx = d.x + 0.62 * d.len; ty = d.y - 0.78 * d.len;
        g = ctx.createLinearGradient(d.x, d.y, tx, ty);
        g.addColorStop(0, rgba(BIO.tint, 0.75)); g.addColorStop(1, rgba(BIO.tint, 0));
        ctx.strokeStyle = g;
        ctx.beginPath(); ctx.moveTo(d.x, d.y); ctx.lineTo(tx, ty); ctx.stroke();
      }
    }

    function drawPath(path, hot) {
      var sprite = hot ? dotHot[path.idx] : dotDim[path.idx];
      var segs = path.segs, half = sprite.width * 0.5, i, s, k, k0, k1, p, y, j, brk = null;
      // a broken stretch of this rope draws nothing: the gap IS the hazard
      for (i = 0; i < items.length; i++) {
        if (items[i].type === "break" && items[i].path === path.idx) (brk || (brk = [])).push(items[i]);
      }
      for (i = 0; i < segs.length; i++) {
        s = segs[i];
        if (s.p1 < pMin || s.p0 > pMax) continue;
        k0 = Math.max(0, Math.floor((pMin - s.p0) / s.step));
        k1 = Math.ceil((Math.min(pMax, s.p1) - s.p0) / s.step);
        for (k = k0; k <= k1; k++) {
          p = s.p0 + k * s.step;
          if (p > s.p1) break;
          if (brk) {
            for (j = 0; j < brk.length; j++) if (p >= brk[j].p && p <= brk[j].p + brk[j].len) break;
            if (j < brk.length) continue;
          }
          segEval(s, p, pp);
          y = sy(pp.y);
          if (y < -40 || y > view.h + 40) continue;
          ctx.drawImage(sprite, pp.x - half, y - half);
        }
      }
    }

    /* A soft glow behind a pickup. A radial gradient, not stacked flat discs:
       a hard-edged disc over the dark background reads as a muddy plate rather
       than as light. Only a handful of pickups are ever on screen, so building
       the gradient per draw is cheaper than caching one sprite per colour. */
    function halo(x, y, r, col) {
      var g = ctx.createRadialGradient(x, y, 0, x, y, r);
      g.addColorStop(0, rgba(col, 0.5));
      g.addColorStop(0.42, rgba(col, 0.16));
      g.addColorStop(1, rgba(col, 0));
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
    }
    /* A gem. The gradient is built INSIDE the rotated frame, so the shading
       spins with the stone (a free glint) instead of being dragged out of the
       shape by the transform. */
    function diamond(x, y, r, rot, top, mid, bot, ink) {
      var g;
      ctx.save(); ctx.translate(x, y); ctx.rotate(rot);
      g = ctx.createLinearGradient(0, -r, 0, r);
      g.addColorStop(0, top);
      if (mid) g.addColorStop(0.5, mid);
      g.addColorStop(1, bot);
      ctx.beginPath();
      ctx.moveTo(0, -r); ctx.lineTo(r * 0.72, 0); ctx.lineTo(0, r); ctx.lineTo(-r * 0.72, 0);
      ctx.closePath();
      ctx.fillStyle = g; ctx.fill();
      ctx.lineWidth = Math.max(3.5, r * 0.2); ctx.strokeStyle = ink; ctx.stroke();
      ctx.restore();
    }
    function spiked(x, y, n, ro, ri, fill, ink, rot) {
      var i, a, r;
      ctx.save(); ctx.translate(x, y); ctx.rotate(rot);
      ctx.beginPath();
      for (i = 0; i < n * 2; i++) {
        a = (i / (n * 2)) * TAU;
        r = i % 2 ? ri : ro;
        if (i === 0) ctx.moveTo(Math.cos(a) * r, Math.sin(a) * r);
        else ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r);
      }
      ctx.closePath();
      ctx.fillStyle = fill; ctx.fill();
      ctx.lineWidth = Math.max(3.5, ro * 0.13); ctx.strokeStyle = ink; ctx.stroke();
      ctx.restore();
    }

    /* Hazards wear NO rope colour. Which rope a mine sits on is told by the grid
       — the columns are a wide, fixed distance apart and the placement rule keeps
       hazards off crossings — so a friendly hue on a mine would buy nothing and
       cost the one thing the item must say instantly: stay away. */
    function drawItem(it, x, y, col) {
      var pu;
      if (it.type === "gem") {
        halo(x, y, 36, col);
        diamond(x, y, 21, runT * 1.6, "#ffffff", null, col, "rgba(4,5,15,.75)");

      } else if (it.type === "star") {
        pu = 1 + Math.sin(runT * 5) * 0.07;
        halo(x, y, 52 * pu, "#ffd43b");
        diamond(x, y, 31 * pu, -runT * 1.2, "#fffbe8", "#ffd43b", "#ff9f1c", "#2b1a00");

      } else if (it.type === "mine") {
        // The loudest thing on screen, and red all the way through: long spikes
        // on a near-black body, turning around a hot core. It is the only item
        // the player MUST read in time, so it is built as a silhouette — seven
        // deep points, so the shape says "do not touch" before the colour does.
        pu = 1 + Math.sin(runT * 7 + it.seed) * 0.09;
        halo(x, y, 66 * pu, "#ff2d55");
        spiked(x, y, 7, 47 * pu, 18, "#2b0410", "#ff2d55", it.seed - runT * 0.85);
        ctx.fillStyle = "#ff2d55";
        ctx.beginPath(); ctx.arc(x, y, 16, 0, TAU); ctx.fill();
        ctx.lineWidth = 3; ctx.strokeStyle = "rgba(255,255,255,.8)";
        ctx.beginPath(); ctx.arc(x, y, 16, 0, TAU); ctx.stroke();
        ctx.fillStyle = "#ffe3ea";
        ctx.beginPath(); ctx.arc(x, y, 6.5, 0, TAU); ctx.fill();

      } else if (it.type === "void") {
        halo(x, y, 54, "#a24bff");
        ctx.fillStyle = "#160a24";
        ctx.beginPath(); ctx.arc(x, y, 31, 0, TAU); ctx.fill();
        ctx.lineWidth = 6; ctx.strokeStyle = "#c07bff";
        ctx.beginPath(); ctx.arc(x, y, 31, 0, TAU); ctx.stroke();
        ctx.fillStyle = "#e8ccff";
        ctx.fillRect(x - 16, y - 4, 32, 8);

      } else if (it.type === "x2") {
        halo(x, y, 46, "#a6ff3d");
        ctx.fillStyle = "#0c2a12";
        ctx.beginPath(); ctx.arc(x, y, 28, 0, TAU); ctx.fill();
        ctx.lineWidth = 5; ctx.strokeStyle = "#a6ff3d";
        ctx.beginPath(); ctx.arc(x, y, 28, 0, TAU); ctx.stroke();
        ctx.fillStyle = "#eaffd0";
        ctx.font = "900 32px -apple-system,Segoe UI,Roboto,sans-serif";
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText("x2", x, y + 1);

      } else if (it.type === "magnet" || it.type === "ghost" || it.type === "slow") {
        // the timed pickups: a badge like the x2's, told apart by its glyph
        pu = it.type === "magnet" ? "#ffc23d" : it.type === "ghost" ? "#dfe6ff" : "#6fc8ff";
        halo(x, y, 46, pu);
        ctx.fillStyle = "#0b0f22";
        ctx.beginPath(); ctx.arc(x, y, 28, 0, TAU); ctx.fill();
        ctx.lineWidth = 5; ctx.strokeStyle = pu;
        ctx.beginPath(); ctx.arc(x, y, 28, 0, TAU); ctx.stroke();
        glyph(it.type, x, y, pu);

      } else {                                            // shield
        halo(x, y, 46, "#8ffff2");
        spiked(x, y, 6, 30, 27, "#062229", "#8ffff2", Math.PI / 6);
        ctx.fillStyle = "#d8fffb";
        ctx.beginPath(); ctx.arc(x, y, 9, 0, TAU); ctx.fill();
      }
    }
    /* The three glyphs: a horseshoe magnet, a little ghost, a clock — drawn,
       so each reads as a silhouette at a glance. */
    function glyph(kind, x, y, col) {
      ctx.save(); ctx.translate(x, y);
      ctx.lineCap = "round"; ctx.lineJoin = "round";
      if (kind === "magnet") {
        ctx.strokeStyle = col; ctx.lineWidth = 8;
        ctx.beginPath(); ctx.arc(0, -2, 11, Math.PI, 0, true); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-11, -2); ctx.lineTo(-11, -12); ctx.moveTo(11, -2); ctx.lineTo(11, -12); ctx.stroke();
        ctx.fillStyle = "#ffffff"; ctx.fillRect(-15, -17, 8, 6); ctx.fillRect(7, -17, 8, 6);
      } else if (kind === "ghost") {
        ctx.fillStyle = col;
        ctx.beginPath(); ctx.arc(0, -4, 12, Math.PI, 0);
        ctx.lineTo(12, 13); ctx.lineTo(6, 8); ctx.lineTo(0, 13); ctx.lineTo(-6, 8); ctx.lineTo(-12, 13);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = "#0b0f22";
        ctx.beginPath(); ctx.arc(-4.5, -4, 2.6, 0, TAU); ctx.arc(4.5, -4, 2.6, 0, TAU); ctx.fill();
      } else {
        ctx.strokeStyle = col; ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, TAU); ctx.stroke();
        ctx.strokeStyle = "#ffffff"; ctx.lineWidth = 4;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, -9); ctx.moveTo(0, 0); ctx.lineTo(7, 4); ctx.stroke();
      }
      ctx.restore();
    }

    /* A LASER: a beam across the whole frame between two emitters, in the
       hazards' red. Little chevrons stand on it over each rope, pointing UP —
       the beam is read as "jump", never as "move". */
    function drawLaser(it, y) {
      var f = 0.75 + 0.25 * Math.sin(runT * 30 + it.seed), i, x;
      ctx.lineCap = "butt";
      ctx.strokeStyle = rgba("#ff2d55", 0.18 * f); ctx.lineWidth = 26;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(view.w, y); ctx.stroke();
      ctx.strokeStyle = rgba("#ff2d55", 0.95); ctx.lineWidth = 7;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(view.w, y); ctx.stroke();
      ctx.strokeStyle = rgba("#ffffff", 0.75 * f); ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(view.w, y); ctx.stroke();
      ctx.fillStyle = "#2b0410";
      ctx.fillRect(Layout.left - 22, y - 16, 22, 32); ctx.fillRect(Layout.right, y - 16, 22, 32);
      ctx.strokeStyle = "#ff2d55"; ctx.lineWidth = 3;
      ctx.strokeRect(Layout.left - 22, y - 16, 22, 32); ctx.strokeRect(Layout.right, y - 16, 22, 32);
      ctx.strokeStyle = "rgba(255,255,255,.9)"; ctx.lineWidth = 4; ctx.lineJoin = "round"; ctx.lineCap = "round";
      for (i = 0; i < 3; i++) {
        x = pathX(i, it.p);
        ctx.beginPath(); ctx.moveTo(x - 12, y - 22); ctx.lineTo(x, y - 34); ctx.lineTo(x + 12, y - 22); ctx.stroke();
      }
    }
    /* A SPRINGBOARD: a pad on its rope in the rope's colour, two white
       chevrons pointing where it throws. */
    function drawPad(it, x, y, col) {
      var d = it.dir, k, sq = 1 - 0.12 * Math.max(0, Math.sin(runT * 9 + it.p));
      ctx.save(); ctx.translate(x, y); ctx.scale(1, sq);
      halo(0, 0, 50, col);
      ctx.fillStyle = "#0b0d1c"; ctx.strokeStyle = col; ctx.lineWidth = 5;
      ctx.beginPath(); ctx.moveTo(-36, -20); ctx.lineTo(36, -20); ctx.lineTo(36, 20); ctx.lineTo(-36, 20); ctx.closePath();
      ctx.fill(); ctx.stroke();
      ctx.strokeStyle = "#ffffff"; ctx.lineWidth = 5; ctx.lineCap = "round"; ctx.lineJoin = "round";
      for (k = 0; k < 2; k++) {
        ctx.beginPath();
        ctx.moveTo(d * (-14 + k * 16) - d * 6, -11); ctx.lineTo(d * (-14 + k * 16) + d * 6, 0); ctx.lineTo(d * (-14 + k * 16) - d * 6, 11);
        ctx.stroke();
      }
      ctx.restore();
    }
    /* A PENDULUM: its track between the two ropes, dashed, a peg on each, and
       the mine riding it — the swing itself is the warning. */
    function drawPendulum(it, y) {
      var xa = pathX(it.path, it.p), xb = pathX(it.b, it.p), mx = pendX(it);
      ctx.strokeStyle = rgba("#ff2d55", 0.4); ctx.lineWidth = 4; ctx.lineCap = "round";
      ctx.setLineDash([10, 12]);
      ctx.beginPath(); ctx.moveTo(xa, y); ctx.lineTo(xb, y); ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = "#ff2d55";
      ctx.beginPath(); ctx.arc(xa, y, 6, 0, TAU); ctx.arc(xb, y, 6, 0, TAU); ctx.fill();
      drawItem({ type: "mine", seed: it.seed }, mx, y, "#ff2d55");
    }
    /* A BLINKING MINE: awake it is a mine; asleep it is its outline, dim,
       with the arc of the time left before it wakes. */
    function drawBlink(it, x, y) {
      var t = (runT / it.period + it.ph) % 1, on = CONFIG.rule.blinkOn, k;
      if (t < on) { drawItem({ type: "mine", seed: it.seed }, x, y, "#ff2d55"); return; }
      k = (t - on) / (1 - on);                         // 0 -> 1 towards waking
      ctx.save(); ctx.globalAlpha = 0.45;
      spiked(x, y, 7, 40, 18, "rgba(43,4,16,.6)", "rgba(255,45,85,.7)", it.seed);
      ctx.restore();
      ctx.strokeStyle = "#ff2d55"; ctx.lineWidth = 4; ctx.lineCap = "round";
      ctx.beginPath(); ctx.arc(x, y, 26, -Math.PI / 2, -Math.PI / 2 + TAU * k); ctx.stroke();
    }
    // A gem riding the jump's arc: raised over its shadow.
    function drawAirGem(it, x, y, col) {
      ctx.fillStyle = "rgba(0,0,0,.35)";
      ctx.beginPath(); ctx.ellipse(x, y + 6, 16, 6, 0, 0, TAU); ctx.fill();
      halo(x, y - T.jumpLift, 34, col);
      diamond(x, y - T.jumpLift, 19, runT * 1.6, "#ffffff", null, col, "rgba(4,5,15,.75)");
    }
    // The torn end of a broken rope: a few sparks, flickering.
    function drawSnap(x, y, seed) {
      var i, a, l, f = Math.floor(runT * 18);
      ctx.lineCap = "round"; ctx.lineWidth = 2.5;
      for (i = 0; i < 4; i++) {
        a = hash(i * 3.7 + f + seed) * TAU; l = 10 + hash(i + f + seed * 2) * 14;
        ctx.strokeStyle = i % 2 ? "#ffffff" : "#ffe9a8";
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); ctx.stroke();
      }
      ctx.fillStyle = "#ffffff";
      ctx.beginPath(); ctx.arc(x, y, 4, 0, TAU); ctx.fill();
    }
    function hash(n) { var v = Math.sin(n * 12.9898) * 43758.5453; return v - Math.floor(v); }
    /* A comet: the mine's red — every hazard speaks it — with a white-hot head,
       its tail laid back UP its own rope so the rope it rides is never in doubt. */
    function drawComet(it, x, y) {
      var q, k, pu = 1 + Math.sin(runT * 14 + it.seed) * 0.08;
      for (q = 224; q >= 16; q -= 16) {
        pathPoint(paths[it.path], it.p + q, pb);
        k = 1 - q / 240;
        ctx.fillStyle = rgba("#ff2d55", 0.55 * k);
        ctx.beginPath(); ctx.arc(pb.x, sy(pb.y), 4 + 12 * k, 0, TAU); ctx.fill();
      }
      halo(x, y, 58 * pu, "#ff2d55");
      ctx.fillStyle = "#ff2d55"; ctx.beginPath(); ctx.arc(x, y, 19 * pu, 0, TAU); ctx.fill();
      ctx.fillStyle = "#fff4f6"; ctx.beginPath(); ctx.arc(x, y + 3, 10, 0, TAU); ctx.fill();
    }

    /* `plain` draws them outside the round's entrance: the guide's pictures
       paint a scene with this same function and must never wait on Enter. */
    function drawItems(plain) {
      var i, it, y, e;
      for (i = 0; i < items.length; i++) {
        it = items[i];
        if (it.type === "break") {
          if (it.p + it.len < pMin || it.p > pMax) continue;
          for (e = 0; e < 2; e++) {
            pathPoint(paths[it.path], it.p + e * it.len, pp);
            y = sy(pp.y);
            if (y < -40 || y > view.h + 40) continue;
            if (plain || Enter.begin(pp.x, y)) { drawSnap(pp.x, y, e * 5 + i); if (!plain) Enter.end(); }
          }
          continue;
        }
        if (it.p < pMin || it.p > pMax) continue;
        if (it.type === "laser") {
          y = sy(it.p);
          if (y > -40 && y < view.h + 40 && (plain || Enter.begin(Layout.cx, y))) { drawLaser(it, y); if (!plain) Enter.end(); }
          continue;
        }
        pathPoint(paths[it.path], it.p, pp);
        y = sy(pp.y);
        if (y < -70 || y > view.h + 70) continue;
        if (plain || Enter.begin(pp.x, y)) {
          if (it.type === "comet") drawComet(it, pp.x, y);
          else if (it.type === "pendulum") drawPendulum(it, y);
          else if (it.type === "blink") drawBlink(it, pp.x, y);
          else if (it.type === "pad") drawPad(it, pp.x, y, paths[it.path].color);
          else if (it.air) drawAirGem(it, pp.x, y, paths[it.path].color);
          else drawItem(it, magnetX(it, pp.x), y, paths[it.path].color);
          if (!plain) Enter.end();
        }
      }
    }

    // Under the magnet a gem close ahead drifts towards the arrow's x.
    function magnetX(it, x) {
      var d;
      if (magnetT <= 0 || (it.type !== "gem" && it.type !== "star")) return x;
      d = it.p - camP;
      if (d < 0 || d > 300) return x;
      return x + (arrowX - x) * (1 - d / 300);
    }

    function drawTrail() {
      var n = trail.length, col = paths[lane].color, pass, i, t;
      if (n < 2 || falling) return;
      ctx.lineCap = "round"; ctx.lineJoin = "round";
      for (pass = 0; pass < 2; pass++) {
        ctx.strokeStyle = pass ? "#ffffff" : rgba(col, 0.5);
        for (i = 1; i < n; i++) {
          t = i / n;
          ctx.globalAlpha = pass ? t * 0.4 : t * 0.75;
          ctx.lineWidth = (pass ? 5 : 16) * t;
          ctx.beginPath();
          ctx.moveTo(trail[i - 1].x, sy(trail[i - 1].y));
          ctx.lineTo(trail[i].x, sy(trail[i].y));
          ctx.stroke();
        }
      }
      ctx.globalAlpha = 1;
    }

    /* The arrow's shape is the biome's. Every one points up (-y) in its own
       frame and fits the chevron's box (about 36 up, 28 down, 34 across), so
       the hop, the lean and the halo need no retuning; each wears the same
       dark contour, because it sits ON a glowing rope and must be cut out of
       it. Chosen in lab/triverse-biomes.html (the Arrows view). */
    function arrowPath(shape) {
      var P, i;
      ctx.beginPath();
      if (shape === "prow") {
        // a beak whose base sits on the ball, so the contour is one line
        ctx.moveTo(0, -38); ctx.lineTo(11.6, -10.3);
        ctx.arc(0, 6, 20, -Math.PI / 2 + 0.62, -Math.PI / 2 - 0.62, false);
      } else {
        P = ARROWS[shape] || ARROWS.chevron;
        ctx.moveTo(P[0], P[1]);
        for (i = 2; i < P.length; i += 2) ctx.lineTo(P[i], P[i + 1]);
      }
      ctx.closePath();
    }
    var ARROWS = {
      chevron: [0, -36, 26, 27, 0, 14, -26, 27],
      trident: [0, -40, 7, -16, 19, -30, 16, 0, 27, 28, 0, 17, -27, 28, -16, 0, -19, -30, -7, -16],
      dart:    [0, -42, 10, -4, 22, 28, 7, 16, 0, 24, -7, 16, -22, 28, -10, -4],
      jet:     [0, -40, 7, -14, 7, -4, 32, 16, 32, 22, 7, 14, 9, 28, 0, 24, -9, 28, -7, 14, -32, 22, -32, 16, -7, -4, -7, -14]
    };

    function drawArrow() {
      var col = paths[lane].color, g, shape = BIO.arrow, h = 0, x, y, ang, sc, al = 1, k;
      if (falling) {
        /* THE FALL: the arrow stays over the hole while it drifts down with
           the world, spinning, shrinking and fading into the dark — the
           player sees WHERE it went and why. */
        k = Math.min(1, fallT / T.fallTime); k = k * k;
        x = fallX; y = sy(fallP); ang = fallAng + k * 7; sc = 1 - 0.85 * k; al = 1 - k;
      } else {
        if (invT > 0 && Math.floor(invT * 14) % 2) return;  // blink while invulnerable
        /* THE JUMP: up off the rope and bigger, over its own shadow left on
           the rope, which is what says how high it is. */
        h = jumpH();
        x = arrowX; y = arrowY - T.jumpLift * h; ang = arrowAng; sc = 1 + 0.45 * h;
        if (h > 0.01) {
          ctx.fillStyle = "rgba(0,0,0," + (0.5 - 0.2 * h).toFixed(3) + ")";
          ctx.beginPath(); ctx.ellipse(arrowX, arrowY + 4, 24 * (1 - 0.35 * h), 9 * (1 - 0.35 * h), 0, 0, TAU); ctx.fill();
        }
        if (ghostT > 0) al = 0.42 + 0.12 * Math.sin(runT * 9);   // a ghost is half there
      }
      ctx.save();
      ctx.globalAlpha = al;
      ctx.translate(x, y);
      // the magnet's reach: a dashed ring turning round the arrow
      if (magnetT > 0 && !falling) {
        ctx.save(); ctx.rotate(runT * 2);
        ctx.setLineDash([12, 10]); ctx.lineWidth = 4; ctx.strokeStyle = rgba("#ffc23d", 0.75);
        ctx.beginPath(); ctx.arc(0, 0, 62, 0, TAU); ctx.stroke();
        ctx.setLineDash([]);
        ctx.restore();
      }
      ctx.rotate(ang + Math.PI / 2);                      // the shape points at -y
      ctx.scale(sc, sc);
      // one soft halo, so the cursor stays readable on top of a rope
      g = ctx.createRadialGradient(0, 0, 0, 0, 0, 54);
      g.addColorStop(0, rgba(col, 0.55));
      g.addColorStop(0.4, rgba(col, 0.2));
      g.addColorStop(1, rgba(col, 0));
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(0, 0, 54, 0, TAU); ctx.fill();
      // the body: white tip, rope-coloured belly, dark contour
      g = ctx.createLinearGradient(0, -40, 0, 28);
      g.addColorStop(0, "#ffffff"); g.addColorStop(0.55, col); g.addColorStop(1, "#ffffff");
      arrowPath(shape);
      ctx.fillStyle = g; ctx.fill();
      ctx.lineJoin = "round"; ctx.lineWidth = 5; ctx.strokeStyle = "rgba(3,4,12,.9)"; ctx.stroke();
      // the detail that makes each shape more than a silhouette
      ctx.lineCap = "round";
      if (shape === "trident" || shape === "dart") {
        ctx.strokeStyle = "rgba(255,255,255,.85)"; ctx.lineWidth = 2.5;
        ctx.beginPath(); ctx.moveTo(0, shape === "trident" ? -30 : -32); ctx.lineTo(0, 10); ctx.stroke();
      } else if (shape === "jet") {
        ctx.fillStyle = "rgba(3,4,12,.75)";
        ctx.beginPath(); ctx.ellipse(0, -16, 3.5, 8, 0, 0, TAU); ctx.fill();
      } else if (shape === "prow") {
        ctx.fillStyle = "rgba(255,255,255,.92)";
        ctx.beginPath(); ctx.arc(0, 6, 8.5, 0, TAU); ctx.fill();
      }
      if (shield) {
        ctx.lineWidth = 4; ctx.strokeStyle = rgba("#8ffff2", 0.85);
        ctx.beginPath(); ctx.arc(0, 0, 42, 0, TAU); ctx.stroke();
      }
      ctx.restore();
    }

    /* FUSION's live rope, drawn to be read from the corner of an eye.
       WARNING (harmless): the rope blinks white-hot on a beat that speeds up,
       a pale electric glow swells along all of it, sparks jump off it, and a
       lightning badge stands on the rope at the arrow's line with the time
       left running out round it — the WHERE and the WHEN in one mark.
       LIVE: three jagged arcs crackle along the whole rope over a wide glow,
       forks break off it, and sparks fly. */
    var ELEC = "#bfe9ff";
    function drawElec() {
      var path = paths[elec.rope], live = camP >= elec.p0, f = Math.floor(runT * 20),
          i, n, k, stop = camP + anchorY + 60, from = camP + anchorY - view.h - 60, bx, by;
      if (!live) {
        k = clamp((camP - elec.start) / Math.max(1, elec.p0 - elec.start), 0, 1);
        ropeLine(path, from, stop, 0, 22 + 14 * k, rgba(ELEC, (0.1 + 0.25 * k) * (0.7 + 0.3 * Math.sin(runT * 20))));
        if (Math.floor(runT * (5 + 11 * k)) % 2) drawPath(path, true);
        n = 6 + Math.round(14 * k);
        for (i = 0; i < n; i++) {
          pathPoint(path, from + hash(i * 7.3 + f) * (stop - from), pp);
          spark(pp.x, sy(pp.y), i + f, 0.6 + 0.4 * k, 1 + k);
        }
        // the badge, on the rope at the arrow's line
        pathPoint(path, camP, pp);
        bx = pp.x; by = sy(pp.y) - 92;
        boltBadge(bx, by, 1 - k);
        return;
      }
      ropeLine(path, from, stop, 0, 34, rgba(ELEC, 0.28));
      ropeLine(path, from, stop, 0, 16, rgba(path.color, 0.6));
      for (i = 0; i < 3; i++) ropeLine(path, from, stop, 22 - i * 6, i ? 2.5 : 4.5, i ? rgba(ELEC, 0.9) : "#ffffff", f * 3 + i * 17);
      // forks: short jagged branches leaving the arc
      ctx.strokeStyle = rgba("#ffffff", 0.85); ctx.lineWidth = 2;
      for (i = 0; i < 7; i++) {
        pathPoint(path, from + hash(i * 5.7 + f) * (stop - from), pp);
        fork(pp.x, sy(pp.y), i + f);
      }
      for (i = 0; i < 14; i++) {
        pathPoint(path, from + hash(i * 3.1 + f) * (stop - from), pp);
        spark(pp.x, sy(pp.y), i * 2 + f, 1, 1.6);
      }
    }
    // A line along the rope, jagged by `jit` px (0: smooth), re-rolled with `seed`.
    function ropeLine(path, from, stop, jit, w, col, seed) {
      var q, first = true, x;
      ctx.lineJoin = "round"; ctx.lineCap = "round";
      ctx.beginPath();
      for (q = from; q <= stop; q += jit ? 22 : 30) {
        pathPoint(path, q, pp);
        x = pp.x + (jit ? (hash(q * 0.013 + (seed || 0)) - 0.5) * jit : 0);
        if (first) { ctx.moveTo(x, sy(pp.y)); first = false; } else ctx.lineTo(x, sy(pp.y));
      }
      ctx.strokeStyle = col; ctx.lineWidth = w; ctx.stroke();
    }
    function fork(x, y, seed) {
      var i, a = (hash(seed * 2.1) - 0.5) * 2.4 + (hash(seed) < 0.5 ? 0 : Math.PI);
      ctx.beginPath(); ctx.moveTo(x, y);
      for (i = 1; i <= 3; i++) {
        x += Math.cos(a) * 12; y += Math.sin(a) * 12;
        a += (hash(seed + i * 1.3) - 0.5) * 1.4;
        ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    // A small spark: three short strokes, white and pale gold, flickering.
    function spark(x, y, seed, a, size) {
      var i, an, l, s = size || 1;
      ctx.lineCap = "round"; ctx.lineWidth = 2 * s;
      ctx.globalAlpha = a;
      for (i = 0; i < 3; i++) {
        an = hash(seed * 1.7 + i) * TAU; l = (6 + hash(seed + i * 2.3) * 10) * s;
        ctx.strokeStyle = i % 2 ? "#ffffff" : "#ffe9a8";
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + Math.cos(an) * l, y + Math.sin(an) * l); ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }
    // The warning badge: a lightning bolt in a dark disc, the time left as an arc.
    function boltBadge(x, y, left) {
      var pu = 1 + 0.08 * Math.sin(runT * 16);
      halo(x, y, 52 * pu, ELEC);
      ctx.fillStyle = "#0b0f22";
      ctx.beginPath(); ctx.arc(x, y, 30, 0, TAU); ctx.fill();
      ctx.lineWidth = 6; ctx.lineCap = "round"; ctx.strokeStyle = rgba(ELEC, 0.25);
      ctx.beginPath(); ctx.arc(x, y, 30, 0, TAU); ctx.stroke();
      ctx.strokeStyle = ELEC;
      ctx.beginPath(); ctx.arc(x, y, 30, -Math.PI / 2, -Math.PI / 2 + TAU * left); ctx.stroke();
      ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.moveTo(x + 4, y - 19); ctx.lineTo(x - 10, y + 3); ctx.lineTo(x - 1, y + 3);
      ctx.lineTo(x - 5, y + 19); ctx.lineTo(x + 10, y - 3); ctx.lineTo(x + 1, y - 3);
      ctx.closePath(); ctx.fill();
    }

    function render() {
      var i;
      ctx.fillStyle = bgGrad;
      ctx.fillRect(0, 0, view.w, view.h);
      drawSparks();
      // The ropes, the pickups and the arrow are the elements of the round's
      // entrance (Enter): the ground and its sparks are there from frame one.
      // the ridden rope last, so it always reads on top of the crossings
      for (i = 0; i < 3; i++) {
        if (i !== lane && Enter.begin(pathX(i, camP), view.h * 0.5)) {
          drawPath(paths[i], false);
          Enter.end();
        }
      }
      if (Enter.begin(pathX(lane, camP), view.h * 0.5)) {
        drawPath(paths[lane], true);
        Enter.end();
      }
      if (elec) drawElec();
      drawItems();
      if (Enter.begin(arrowX, arrowY)) {
        drawTrail();
        drawArrow();
        Enter.end();
      }
    }

    function onResize() { metrics(); }

    /* --- THE LEVEL LAYER (web target) ------------------------------------
       `levelProgress` is what a level's objective is measured against while
       the round runs, and it is the same number the result reports as
       `levelScore`: the METRES, never the score, so pickups cannot pay for a
       distance. `levelWon` is the three-star finish — the web shell has
       already played the slow motion, and the round ends through the game's
       own result so the end screen keeps these stat rows. Both are ignored by
       the playable, which has no levels — see docs/LEVELS.md. */
    function levelProgress() { return Math.floor(dist); }

    /* `applyLevel(d)` is called after the manifest's knobs are lerped and
       BEFORE reset(): it picks the biome off the LEVEL NUMBER (the two roads
       out of a fork are the same world), the rules that come with it and how
       often they come — from `rule.rate[0]` on the stretch's first level to
       `rate[1]` on its last. `null` is a free round and the endless run: NEON,
       no rule, the game as it always was. The playable never calls it. */
    function applyLevel(d) {
      var n = CONFIG.level | 0, i, from = CONFIG.biomeFrom, B = CONFIG.biomes;
      BIO = B[0]; RULES = []; RATE = 0; STEP = 0;
      if (n && d != null) {
        for (i = 0; i < from.length; i++) if (n >= from[i]) BIO = B[i];
        STEP = clamp((n - from[B.indexOf(BIO)]) / 5, 0, 1);
        RULES = BIO.rules;
        // Fusion deals every older rule on top of its own live rope: they share one rate
        RATE = RULES.indexOf("elec") >= 0 ? CONFIG.rule.mixRate : RULES.length ? lerpRule(CONFIG.rule.rate) : 0;
      }
      FIG = FIGURES.concat(BIO.figures);
    }

    /* --- the guide: every rule, as pages (packages/webshell/guide.js) -----
       Every page SHOWS before it tells, and its picture is a scene of the
       round painted by the round's own renderers — drawPath, drawItems,
       drawArrow, drawElec — with the round's `ctx` lent to a canvas of its
       own for the length of the call. The scene borrows every piece of round
       state those renderers read and puts it back in `finally`, so a picture
       drawn before the first round (from the title screen's Help card) reads
       nothing unset, and one drawn over a paused round changes nothing of it.
       The scene is laid out in the design space and scaled to the picture,
       cropped to the 620 px around the three ropes, so they stand on the same
       grid as in a round. */
    var PIC_W = 520, PIC_K = PIC_W / 620;
    function rail(i) { return { k: 0, p0: -6000, p1: 6000, x: slotX(i), step: T.dot }; }
    /* `bi` is the biome, `H` the picture's height in px; `setup(o, Hd)` lays
       the scene out (items, lanes, timers) before anything is drawn, and may
       turn off the arrow (`o.arrow`) or the sky (`o.sky`). */
    function scenePic(bi, H, setup) {
      var cv = document.createElement("canvas"), k = view.dpr || 1, keep = ctx, Hd = H / PIC_K,
          o = { arrow: true, sky: true, t: 0.4 }, i, g, q, mine,
          S = [BIO, paths, items, trail, camP, runT, anchorY, pMin, pMax, lane, prevLane, switchT, switchDir,
               arrowX, arrowY, arrowAng, jumpP, falling, fallT, magnetT, ghostT, shield, invT, mult,
               dotDim, dotHot, dotKey, sparks, glowGrad, beamGrad, sway, elec, flashT, bolt, deco];
      cv.width = Math.round(PIC_W * k); cv.height = Math.round(H * k);
      cv.style.width = PIC_W + "px"; cv.style.height = H + "px";
      ctx = cv.getContext("2d"); ctx.scale(k * PIC_K, k * PIC_K); ctx.translate(310 - Layout.cx, 0);
      try {
        BIO = CONFIG.biomes[bi]; sway = 0;
        dotDim = []; dotHot = []; dotKey = ""; buildDots(); mine = [dotDim, dotHot];
        camP = 0; runT = 0; anchorY = Hd - 76; pMin = anchorY - Hd - 240; pMax = anchorY + 240;
        lane = 1; prevLane = 1; switchT = 1; switchDir = 0; jumpP = -1e9; falling = false; fallT = 0;
        magnetT = 0; ghostT = 0; shield = false; invT = 0; mult = 1;
        elec = null; flashT = 0; bolt = null; deco = []; items = []; trail = [];
        paths = [];
        for (i = 0; i < 3; i++) paths.push({ idx: i, color: BIO.ropes[i], segs: [rail(i)] });
        if (setup) setup(o, Hd);
        // the arrow's place first: the magnet's pull is read off it
        for (q = -200; q <= -40; q += 12) { pathPoint(paths[prevLane], q, pa); trail.push({ x: pa.x, y: pa.y }); }
        updateArrow();

        // the ground: the biome's own gradient, centred on this frame
        g = ctx.createRadialGradient(360, Hd * 0.3, 30, 360, Hd * 0.42, Hd * 1.1);
        g.addColorStop(0, BIO.ground[0]); g.addColorStop(0.55, BIO.ground[1]); g.addColorStop(1, BIO.ground[2]);
        ctx.fillStyle = g; ctx.fillRect(0, 0, 720, Hd);
        if (o.sky) {
          // the biome's sky, its field folded into this frame's height
          buildSparks();
          for (i = 0; i < sparks.length; i++) sparks[i].y = sparks[i].y * (Hd + 80) / (view.h + 80);
          glowGrad = null;
          if (BIO.glow) {
            glowGrad = ctx.createRadialGradient(360, Hd * 1.08, 20, 360, Hd * 1.08, Hd * 0.9);
            glowGrad.addColorStop(0, rgba(BIO.glow[0], BIO.glow[1]));
            glowGrad.addColorStop(1, rgba(BIO.glow[0], 0));
          }
          beamGrad = ctx.createLinearGradient(-90, 0, 90, 0);
          beamGrad.addColorStop(0, rgba(BIO.tint, 0));
          beamGrad.addColorStop(0.5, rgba(BIO.tint, 0.07));
          beamGrad.addColorStop(1, rgba(BIO.tint, 0));
          drawSparks();
        }
        runT = o.t;
        for (i = 0; i < 3; i++) if (i !== lane) drawPath(paths[i], false);
        drawPath(paths[lane], true);
        if (elec) drawElec();
        drawItems(true);
        if (o.arrow) { drawTrail(); drawArrow(); }   // its trail down the rope it came from
      } finally {
        if (mine) for (i = 0; i < 3; i++) { freeCanvas(mine[0][i]); freeCanvas(mine[1][i]); }
        BIO = S[0]; paths = S[1]; items = S[2]; trail = S[3]; camP = S[4]; runT = S[5]; anchorY = S[6];
        pMin = S[7]; pMax = S[8]; lane = S[9]; prevLane = S[10]; switchT = S[11]; switchDir = S[12];
        arrowX = S[13]; arrowY = S[14]; arrowAng = S[15]; jumpP = S[16]; falling = S[17]; fallT = S[18];
        magnetT = S[19]; ghostT = S[20]; shield = S[21]; invT = S[22]; mult = S[23];
        dotDim = S[24]; dotHot = S[25]; dotKey = S[26]; sparks = S[27]; glowGrad = S[28]; beamGrad = S[29];
        sway = S[30]; elec = S[31]; flashT = S[32]; bolt = S[33]; deco = S[34];
        ctx = keep;
      }
      return cv;
    }
    // what a scene puts on a rope
    function put(type, path, p, more) {
      var it = { type: type, path: path, p: p, seed: 0.6 }, k;
      for (k in more || {}) it[k] = more[k];
      items.push(it);
    }
    function gemRun(path, p0, n, gap) { for (var i = 0; i < n; i++) put("gem", path, p0 + i * gap); }
    function fill(s, v) { return s.replace(/\{(\w+)\}/g, function (m, k) { return v[k] != null ? v[k] : m; }); }
    // the level a biome opens on, and its last one
    function bioSpan(i) {
      var f = CONFIG.biomeFrom;
      return { a: f[i], b: i + 1 < f.length ? f[i + 1] - 1 : 30 };
    }
    function bioPage(i, id, title, lines, setup) {
      var s = bioSpan(i);
      return { id: id, title: title, lv: s.a, lines: lines,
               pic: function () { return scenePic(i, 280, setup); } };
    }
    // every string a page carries is already in the player's language
    function page(id, title, lv, lines, pic, rows) {
      return { id: id, title: title, lv: lv, lines: lines, pic: pic, rows: rows };
    }
    var guide = {
      chapters: function () {
        var F = CONFIG.biomeFrom, E = CONFIG.rule.elec;
        return [
          { key: "basics", label: Lang.t("The basics"), pages: [
            page("ropes", Lang.t("Three ropes"), 0, [
              Lang.t("Swipe left or right, or tap beside the arrow, to hop onto the next rope.")
            ], function () {
              return scenePic(0, 240, function (o) {
                prevLane = 1; lane = 2; switchT = 0.55; switchDir = 1;
                gemRun(2, 120, 3, 80);
              });
            }),
            page("jump", Lang.t("The jump"), 0, [
              Lang.t("Swipe up, or tap the arrow, to jump. You can still change rope in the air."),
              Lang.t("Holes and lasers pass under you. Mines are too tall to jump over.")
            ], function () {
              return scenePic(0, 280, function () {
                jumpP = -T.jumpLen * 0.45;
                put("gem", 1, 150, { air: true }); put("gem", 1, 240, { air: true });
              });
            }),
            page("goal", Lang.t("The run"), 0, [
              Lang.t("Each level asks for a distance. Gems raise the score, never the distance.")
            ], function () { return scenePic(0, 200, null); }),
            page("score", Lang.t("Scoring"), 0, [
              Lang.t("Every gem grows your chain. A crash, a fall or a void breaks it.")
            ], function () {
              return scenePic(0, 200, function () { gemRun(1, 40, 2, 70); put("star", 2, 100); });
            },
            [[Lang.t("A mega gem"), "120", "#ffd43b"], [Lang.t("A chain of 6, 12…"), "+50, +100…"]]),
            page("hazards", Lang.t("Mines and voids"), 0, [
              Lang.t("A void costs no life, but drains points and breaks the chain.")
            ], function () {
              return scenePic(0, 240, function () { put("mine", 0, 150); put("void", 2, 150); gemRun(1, 80, 2, 70); });
            },
            [[Lang.t("A mine"), Lang.t("−1 life"), "#ff2d55"], [Lang.t("A void"), "−70", "#c07bff"]]),
            page("pair", Lang.t("Mine pairs"), 0, [
              Lang.t("When two mines block two ropes, the third one is always open.")
            ], function () {
              return scenePic(0, 280, function () { put("mine", 0, 180); put("mine", 2, 180); });
            }, [[Lang.t("Through the open rope"), "+60"]]),
            page("loops", Lang.t("Loops and figures"), 0, [
              Lang.t("Ride a figure to the end to score it. Leaving it halfway pays nothing.")
            ], function () {
              return scenePic(0, 240, function () {
                var r = 70, sp = r * 2.3, x = slotX(1), p0 = 40;
                paths[1].segs = [{ k: 0, p0: -6000, p1: p0, x: x, step: T.dot },
                                 { k: 3, p0: p0, p1: p0 + sp, x: x, r: r, dir: 1, step: dotStep(3, r, sp / TAU), n: 2 },
                                 { k: 3, p0: p0 + sp, p1: p0 + sp * 2, x: x, r: r, dir: -1, step: dotStep(3, r, sp / TAU), n: 2 },
                                 { k: 0, p0: p0 + sp * 2, p1: 6000, x: x, step: T.dot }];
              });
            })
          ] },
          { key: "pickups", label: Lang.t("Pickups"), pages: [
            page("x2", Lang.t("Score x2"), 0, [
              Lang.t("Every gem, chain, loop and mine pair pays double.")
            ], function () {
              return scenePic(0, 260, function () { put("x2", 1, 180); gemRun(2, 140, 2, 80); });
            }),
            page("shield", Lang.t("Shield"), 0, [
              Lang.t("The shield takes one crash for you. You lose no life and keep your chain."),
              Lang.t("The shield won't stop you falling into a hole.")
            ], function () {
              return scenePic(0, 260, function () { shield = true; put("shield", 1, 180); });
            }),
            page("magnet", Lang.t("Magnet"), 0, [
              Lang.t("The magnet pulls in the gems of all three ropes, but not the ones in the air.")
            ], function () {
              return scenePic(0, 280, function () {
                magnetT = 3; put("magnet", 1, 230);
                put("gem", 0, 90); put("gem", 0, 180); put("gem", 2, 120); put("gem", 2, 210);
              });
            }),
            page("ghost", Lang.t("Ghost"), F[1], [
              Lang.t("Mines, voids, lasers, comets and live ropes pass through you."),
              Lang.t("You still fall into holes.")
            ], function () {
              return scenePic(1, 260, function () { ghostT = 3; put("mine", 1, 6); put("ghost", 1, 180); });
            }),
            page("slow", Lang.t("Slow down"), F[2], [
              Lang.t("You drop back to the level's starting speed, then speed up again.")
            ], function () {
              return scenePic(2, 260, function () { put("slow", 1, 180); });
            })
          ] },
          { key: "neon", label: Lang.t("Neon"), pages: [
            bioPage(0, "neon", Lang.t("Neon"), [
              Lang.t("Here you meet springboards, plus the score x2, the shield and the magnet.")
            ], function () { gemRun(0, 120, 3, 80); put("mine", 2, 230); }),
            page("pad", Lang.t("Springboards"), F[0], [
              Lang.t("A springboard throws you onto the next rope, the way its chevrons point."),
              Lang.t("The bounce counts as a jump, so holes and lasers pass under you.")
            ], function () {
              return scenePic(0, 300, function () { put("pad", 1, 190, { dir: 1 }); });
            })
          ] },
          { key: "prism", label: Lang.t("Prism"), pages: [
            bioPage(1, "prism", Lang.t("Prism"), [
              Lang.t("Here you meet lasers, blinking mines and the ghost.")
            ], function () { gemRun(2, 110, 3, 80); }),
            page("laser", Lang.t("Lasers"), F[1], [
              Lang.t("A laser crosses all three ropes, so changing rope won't help."),
              Lang.t("Swipe up to jump the laser.")
            ], function () {
              return scenePic(1, 280, function () {
                put("laser", -1, 210);
                put("gem", 1, 130, { air: true }); put("gem", 1, 250, { air: true });
              });
            }),
            page("blink", Lang.t("Blinking mines"), F[1], [
              Lang.t("A blinking mine sleeps and wakes to a rhythm. Its arc counts down until it wakes up."),
              Lang.t("Dodge a blinking mine, or ride through it while it sleeps.")
            ], function () {
              return scenePic(1, 260, function () {
                put("blink", 0, 200, { period: 1.5, ph: 0 });
                put("blink", 2, 200, { period: 1.5, ph: 0.5 });
              });
            })
          ] },
          { key: "storm", label: Lang.t("Storm"), pages: [
            bioPage(2, "storm", Lang.t("Storm"), [
              Lang.t("Here you meet holes in the ropes, and the slow down.")
            ], function () {
              flashT = 0.3; bolt = [520, -20, 490, 50, 540, 120, 500, 190, 550, 250];
              gemRun(0, 120, 3, 80);
            }),
            page("break", Lang.t("Holes"), F[2], [
              Lang.t("Jump over a hole, or switch rope before it and come back after."),
              Lang.t("Neither the shield nor the ghost will stop you falling.")
            ], function () {
              return scenePic(2, 300, function () {
                jumpP = -90;
                put("break", 1, 60, { len: 150 });
                put("gem", 1, 85, { air: true }); put("gem", 1, 135, { air: true }); put("gem", 1, 185, { air: true });
              });
            })
          ] },
          { key: "comets", label: Lang.t("Comets"), pages: [
            bioPage(3, "comets", Lang.t("Comets"), [
              Lang.t("Here you meet comets and pendulums.")
            ], function () { deco = [{ x: 640, y: 30, len: 230 }]; gemRun(2, 120, 3, 80); }),
            page("comet", Lang.t("Comets"), F[3], [
              Lang.t("A comet slides down its rope towards you, faster than the ropes scroll."),
              Lang.t("Leave the comet's rope before it reaches you.")
            ], function () {
              return scenePic(3, 280, function () { put("comet", 1, 150); });
            }),
            page("pendulum", Lang.t("Pendulums"), F[3], [
              Lang.t("A pendulum's mine swings between two ropes, and the third one always stays clear.")
            ], function () {
              return scenePic(3, 260, function () {
                lane = prevLane = 2;
                put("pendulum", 0, 200, { b: 1, w: TAU / 1.75, ph: -0.2 });
              });
            })
          ] },
          { key: "fusion", label: Lang.t("Fusion"), pages: [
            bioPage(4, "fusion", Lang.t("Fusion"), [
              Lang.t("Here you meet live ropes.")
            ], function () { gemRun(0, 120, 3, 80); put("blink", 2, 220, { period: 1.3, ph: 0 }); }),
            page("elec", Lang.t("Live ropes"), F[4], [
              fill(Lang.t("A rope sparks for {w} s first. It is only a warning, and harmless."), { w: E.warn }),
              fill(Lang.t("Then the rope goes live for {l} s. Get off it, or be in the air."), { l: E.live })
            ], function () {
              return scenePic(4, 280, function () {
                elec = { rope: 2, start: -600, p0: 60, p1: 900, live: false, liveT: 0, hit: false };
              });
            })
          ] }
        ];
      }
    };

    return { reset: reset, update: update, render: render,
             onDown: onDown, onMove: onMove, onUp: onUp, onResize: onResize,
             levelProgress: levelProgress, levelWon: die, applyLevel: applyLevel, guide: guide };
  })();

